/* ================================================================
   EXPLORAR — busca (autor, palavra, trecho ou frase) + filtro por categoria + grid
   ================================================================ */
function renderCategoryChips(){
  const el = document.getElementById('categoryChips');
  // Todos os 22 campos + "Todos os temas" ficam sempre acessíveis:
  // no celular por arraste lateral (carrossel), no desktop pelas setas.
  const chips = [{id:'all', name:'Todos os temas'}, ...CATEGORIES];
  el.innerHTML = chips.map(c=>`<button class="chip ${state.exploreFilter.cat===c.id?'active':''}" data-chip="${c.id}">${c.name}</button>`).join('');
  el.querySelectorAll('.chip').forEach(chip=>{
    chip.addEventListener('click', ()=>{
      state.exploreFilter.cat = chip.dataset.chip;
      el.querySelectorAll('.chip').forEach(c=>c.classList.toggle('active', c===chip));
      clearRandomSlot();
      centerActiveChip();
      renderExploreResults();
      keepResultsInView();
    });
  });
  requestAnimationFrame(()=>{ centerActiveChip(true); updateChipArrows(); });
}
/* ---- carrossel dos campos: setas (desktop) + arraste lateral (celular) ---- */
function chipRowEl(){ return document.getElementById('categoryChips'); }
function updateChipArrows(){
  const row = chipRowEl();
  const prev = document.getElementById('chipPrev');
  const next = document.getElementById('chipNext');
  if(!row || !prev || !next) return;
  const max = row.scrollWidth - row.clientWidth - 2;
  prev.disabled = row.scrollLeft <= 2;
  next.disabled = row.scrollLeft >= max;
}
function scrollChips(dir){
  const row = chipRowEl();
  if(!row) return;
  const step = Math.max(180, Math.round(row.clientWidth * 0.7));
  row.scrollBy({ left: dir*step, behavior: prefersReducedMotion() ? 'auto' : 'smooth' });
}
function centerActiveChip(instant=false){
  const row = chipRowEl();
  if(!row) return;
  const active = row.querySelector('.chip.active');
  if(!active) return;
  const target = active.offsetLeft - (row.clientWidth/2) + (active.offsetWidth/2);
  const left = Math.max(0, Math.min(target, row.scrollWidth - row.clientWidth));
  if(instant || prefersReducedMotion()) row.scrollLeft = left;
  else row.scrollTo({ left, behavior:'smooth' });
}
function prefersReducedMotion(){
  return window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
}
document.getElementById('chipPrev').addEventListener('click', ()=>scrollChips(-1));
document.getElementById('chipNext').addEventListener('click', ()=>scrollChips(1));
document.getElementById('categoryChips').addEventListener('scroll', updateChipArrows, { passive:true });
window.addEventListener('resize', updateChipArrows);

/* ---- frase aleatória do campo selecionado ---- */
function clearRandomSlot(){
  const slot = document.getElementById('randomSlot');
  if(!slot) return;
  slot.innerHTML = '';
  slot.classList.add('hidden');
}
function drawRandomFromField(){
  const pool = getFilteredQuotes();          // já respeita o campo selecionado
  const slot = document.getElementById('randomSlot');
  if(pool.length === 0){ clearRandomSlot(); toast('Nenhuma frase para sortear aqui'); return; }
  let pick = pool[0];
  if(pool.length > 1){
    do{ pick = pool[Math.floor(Math.random()*pool.length)]; } while(pick.idx === state.lastFieldRandomIdx);
  }
  state.lastFieldRandomIdx = pick.idx;
  const catName = state.exploreFilter.cat === 'all'
    ? 'todos os temas'
    : (catById(state.exploreFilter.cat)?.name || '');
  slot.innerHTML = `
    <div class="random-slot-head">
      <span class="random-slot-label">Frase sorteada · ${escapeHtml(catName)}</span>
      <button class="random-slot-close" id="randomSlotClose" type="button" aria-label="Fechar frase sorteada">✕</button>
    </div>
    <div class="random-slot-card">${quoteCardHTML(pick.quote, pick.idx)}</div>`;
  slot.classList.remove('hidden');
  attachQuoteCardEvents(slot);
  document.getElementById('randomSlotClose').addEventListener('click', clearRandomSlot);
}
document.getElementById('randomFieldBtn').addEventListener('click', drawRandomFromField);
// Normaliza para busca: minúsculas + remove acentos (educacao encontra educação)
function normalizeSearch(str){
  return String(str).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();
}
function getFilteredQuotes(){
  const { cat, q } = state.exploreFilter;
  const query = normalizeSearch(q);
  const queryWords = query.split(/\s+/).filter(Boolean);
  return QUOTES.map((quote,idx)=>({quote,idx})).filter(({quote})=>{
    const matchesCat = quoteMatchesCat(quote, cat);
    if(!matchesCat) return false;
    if(!query) return true;
    const haystack = normalizeSearch(quote.author + ' ' + quote.text);
    // Corresponde se: o trecho completo aparece OU todas as palavras da busca aparecem (em qualquer ordem)
    return haystack.includes(query) || queryWords.every(w => haystack.includes(w));
  });
}
/* Entrega dos cartões em lotes conforme a rolagem.
   Mesmos cartões, mesma ordem e mesmo HTML de antes — só não montamos
   milhares de nós de uma vez, o que travaria o celular. A contagem
   exibida continua sendo a do total de resultados. */
// Lotes menores no celular (menos trabalho por quadro), maiores no desktop.
function exploreBatchSize(){
  const w = window.innerWidth || 1024;
  return w < 600 ? 18 : w < 1000 ? 30 : 48;
}
let exploreQueue = [];
let exploreFilling = false;

/* Ao trocar de tema, a lista encurta e o usuário pode ficar "pendurado"
   num trecho vazio da página. Reancoramos a rolagem no topo dos resultados. */
function keepResultsInView(){
  const bar = document.querySelector('#view-explorar .results-bar');
  if(!bar) return;
  const top = bar.getBoundingClientRect().top + window.scrollY - 96;
  if(window.scrollY > top){
    const suave = !window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    window.scrollTo({ top: Math.max(0, top), behavior: suave ? 'smooth' : 'auto' });
  }
}

function appendExploreBatch(){
  const grid = document.getElementById('exploreGrid');
  if(!grid || !exploreQueue.length) return;
  const batch = exploreQueue.splice(0, exploreBatchSize());
  const holder = document.createElement('div');
  holder.innerHTML = batch.map(({quote,idx})=>quoteCardHTML(quote, idx)).join('');
  // uma única inserção no DOM por lote (evita recalcular layout cartão a cartão)
  const frag = document.createDocumentFragment();
  const novos = [];
  while(holder.firstElementChild){
    const card = holder.firstElementChild;
    novos.push(card);
    frag.appendChild(card);
  }
  grid.appendChild(frag);
  novos.forEach(attachQuoteCardEvents);
}
// Enche enquanto o fim da lista estiver perto da tela; para quando sai de vista.
function fillExploreWhileVisible(){
  if(exploreFilling || !exploreQueue.length) return;
  const view = document.getElementById('view-explorar');
  if(!view || view.classList.contains('hidden')) return;
  const sentinel = document.getElementById('exploreSentinel');
  if(!sentinel) return;
  const r = sentinel.getBoundingClientRect();
  if(!r.height && !r.top && !r.bottom) return;            // sem layout (view oculta)
  if(r.top > window.innerHeight + 900) return;            // ainda longe do fim
  exploreFilling = true;
  appendExploreBatch();
  requestAnimationFrame(()=>{ exploreFilling = false; fillExploreWhileVisible(); });
}
let exploreTick = false;
function onExploreScroll(){
  if(exploreTick) return;
  exploreTick = true;
  requestAnimationFrame(()=>{ exploreTick = false; fillExploreWhileVisible(); });
}
window.addEventListener('scroll', onExploreScroll, { passive:true });
window.addEventListener('resize', onExploreScroll, { passive:true });
window.addEventListener('orientationchange', onExploreScroll, { passive:true });

function renderExploreResults(){
  const results = getFilteredQuotes();
  const grid = document.getElementById('exploreGrid');
  const empty = document.getElementById('exploreEmpty');
  const count = document.getElementById('resultsCount');
  const { q } = state.exploreFilter;
  count.textContent = q.trim()
    ? `${results.length} resultado${results.length===1?'':'s'} para "${q.trim()}"`
    : `${results.length} frase${results.length===1?'':'s'}`;
  grid.innerHTML = '';
  exploreQueue = results;
  if(results.length===0){
    empty.classList.remove('hidden');
  }else{
    empty.classList.add('hidden');
    appendExploreBatch();
    requestAnimationFrame(fillExploreWhileVisible);
  }
}
function renderExplore(){
  renderCategoryChips();
  document.getElementById('authorSearch').value = state.exploreFilter.q;
  document.getElementById('clearSearch').classList.toggle('hidden', !state.exploreFilter.q);
  clearRandomSlot();
  renderExploreResults();
}
let searchDebounce;
document.getElementById('authorSearch').addEventListener('input', (e)=>{
  state.exploreFilter.q = e.target.value;
  document.getElementById('clearSearch').classList.toggle('hidden', !e.target.value);
  clearRandomSlot();
  clearTimeout(searchDebounce);
  searchDebounce = setTimeout(renderExploreResults, 150);
});
document.getElementById('clearSearch').addEventListener('click', ()=>{
  state.exploreFilter.q='';
  document.getElementById('authorSearch').value='';
  document.getElementById('clearSearch').classList.add('hidden');
  clearRandomSlot();
  renderExploreResults();
});

/* ================================================================
   HISTÓRIAS — cartões com narração por voz sob demanda
   Usa a Web Speech API nativa do navegador (speechSynthesis).
   A narração é gerada em tempo real a cada clique no botão de
   reprodução — não há áudio pré-gravado.
   ================================================================ */
let voicesCache = null;
function loadVoices(){
  return new Promise(resolve=>{
    let voices = speechSynthesis.getVoices();
    if(voices.length){ resolve(voices); return; }
    speechSynthesis.onvoiceschanged = ()=> resolve(speechSynthesis.getVoices());
    setTimeout(()=>resolve(speechSynthesis.getVoices()), 1200);
  });
}
function pickVoice(voices, genderPref){
  const ptVoices = voices.filter(v=>v.lang && v.lang.toLowerCase().startsWith('pt'));
  const pool = ptVoices.length ? ptVoices : voices;
  const femaleHints = ['female','mulher','maria','luciana','fernanda','feminin','woman','girl','joana','vitoria','vitória'];
  const maleHints = ['male','homem','daniel','ricardo','masculin','man','felipe','diego','marcos'];
  const hints = genderPref==='female' ? femaleHints : maleHints;
  let match = pool.find(v=> hints.some(h=>v.name.toLowerCase().includes(h)));
  if(!match && pool.length>1){ match = genderPref==='female' ? pool[0] : pool[1]; }
  return match || pool[0] || voices[0];
}
let currentAudio = { id:null, utterance:null };
async function toggleStoryAudio(storyId, text, btn, statusEl, voiceSel){
  if(!('speechSynthesis' in window)){ toast('Seu navegador não suporta narração por voz.'); return; }

  if(currentAudio.id === storyId){
    speechSynthesis.cancel();
    resetAudioUI(storyId, btn, statusEl);
    return;
  }
  speechSynthesis.cancel();
  document.querySelectorAll('.play-btn.playing').forEach(b=>{
    b.classList.remove('playing');
    b.innerHTML = playIconSVG();
  });

  btn.innerHTML = `<svg viewBox="0 0 24 24" width="14" height="14"><rect x="3" y="3" width="18" height="18" rx="2" fill="currentColor"/></svg>`;
  btn.classList.add('playing');
  statusEl.innerHTML = `<span class="eq"><span></span><span></span><span></span></span> Gerando narração…`;
  currentAudio.id = storyId;

  const voices = await loadVoices();
  const voice = pickVoice(voices, voiceSel.value);
  const utter = new SpeechSynthesisUtterance(text);
  if(voice) utter.voice = voice;
  utter.lang = (voice && voice.lang) || 'pt-BR';
  utter.rate = 0.98; utter.pitch = 1;
  utter.onstart = ()=>{ statusEl.innerHTML = `<span class="eq"><span></span><span></span><span></span></span> Reproduzindo com voz ${voiceSel.value==='female'?'feminina':'masculina'}…`; };
  utter.onend = ()=> resetAudioUI(storyId, btn, statusEl);
  utter.onerror = ()=>{ resetAudioUI(storyId, btn, statusEl); toast('Não foi possível narrar agora. Tente novamente.'); };
  currentAudio.utterance = utter;
  speechSynthesis.speak(utter);
}
function resetAudioUI(storyId, btn, statusEl){
  if(currentAudio.id===storyId) currentAudio.id = null;
  btn.classList.remove('playing');
  btn.innerHTML = playIconSVG();
  statusEl.textContent = 'Toque para ouvir';
}
function playIconSVG(){
  return `<svg viewBox="0 0 24 24" width="15" height="15" fill="currentColor"><path d="M8 5v14l11-7L8 5Z"/></svg>`;
}
function storyCoverHTML(s, i){
  const base = catColor(s.cat);
  const bg = `linear-gradient(135deg, ${base}, color-mix(in srgb, ${base} 65%, black))`;
  const src = s.photo || localStoryPhoto(slugify(s.author)) || NO_IMG;
  return `<div class="story-cover" style="background:${bg};">
      <img src="${src}" alt="${escapeHtml(s.author)}" loading="lazy" onerror="this.style.display='none'; this.nextElementSibling.style.display='flex';">
      <span class="story-cover-fallback" style="display:none;">${initials(s.author)}</span>
    </div>`;
}
function storyCardHTML(s, i, expanded=false){
  const cat = catById(s.cat);
  return `
  <article class="story-card reveal in-view">
    ${storyCoverHTML(s, i)}
    <div class="story-body">
      <span class="story-cat">${cat?cat.name:''}</span>
      <h3 class="story-title">${escapeHtml(s.title)}</h3>
      <p class="story-excerpt">${escapeHtml(s.excerpt)}</p>
      <div class="story-full-wrap hidden" data-full-for="${s.id}">
        <p class="story-full">${escapeHtml(s.text).replace(/\n\n/g,'</p><p class="story-full">')}</p>
      </div>
      <button class="story-toggle" data-story-toggle="${s.id}">Ler biografia completa ↓</button>
      <div class="story-audio">
        <button class="play-btn" data-story-play="${s.id}" aria-label="Reproduzir narração">${playIconSVG()}</button>
        <select class="voice-select" data-voice-for="${s.id}">
          <option value="female">Voz feminina</option>
          <option value="male">Voz masculina</option>
        </select>
        <span class="audio-status" data-status-for="${s.id}">Toque para ouvir</span>
      </div>
    </div>
  </article>`;
}
function renderStoriesGrid(containerId, list){
  const el = document.getElementById(containerId);
  el.innerHTML = list.map((s,i)=>storyCardHTML(s,i)).join('');
  // Todas as buscas abaixo são relativas ao próprio cartão (closest), nunca globais —
  // assim funcionam corretamente mesmo quando a mesma história aparece em mais de
  // um lugar da página (ex: prévia na Início + grade completa em Histórias).
  el.querySelectorAll('[data-story-toggle]').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const card = btn.closest('.story-card');
      const box = card.querySelector('[data-full-for]');
      const isHidden = box.classList.contains('hidden');
      box.classList.toggle('hidden');
      btn.textContent = isHidden ? 'Ler menos ↑' : 'Ler biografia completa ↓';
    });
  });
  el.querySelectorAll('[data-story-play]').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const id = btn.dataset.storyPlay;
      const card = btn.closest('.story-card');
      const statusEl = card.querySelector('[data-status-for]');
      const voiceSel = card.querySelector('[data-voice-for]');
      const story = STORIES.find(s=>s.id===id);
      toggleStoryAudio(id, `${story.title}. ${story.text}`, btn, statusEl, voiceSel);
    });
  });
}

/* ================================================================
   COMPOSITOR (usado na Comunidade e em Minhas Frases)
   Permite alternar fonte, cor e "papel de fundo" da publicação.
   ================================================================ */
function composerHTML(mode){
  const styleRef = mode==='myphrases' ? state.myPhraseStyle : state.composerStyle;
  const placeholder = mode==='myphrases'
    ? 'Escreva algo só para você — um pensamento, uma meta, um lembrete gentil…'
    : 'O que está vivendo hoje? Compartilhe uma frase ou um pequeno relato…';
  const btnLabel = mode==='myphrases' ? 'Salvar para mim' : 'Publicar na comunidade';
  return `
  <div class="composer">
    ${mode==='myphrases' ? `
      <div class="privacy-note">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="4" y="10" width="16" height="10" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg>
        Isto é privado. Só você pode ver o que escrever aqui.
      </div>` : ''}
    <div class="composer-head">
      ${state.currentUser ? `<div class="composer-avatar" style="background:${colorForName(state.currentUser.username)}; display:flex; align-items:center; justify-content:center; color:#fff; font-weight:800; font-size:13px;">${initials(state.currentUser.username)}</div><b>${escapeHtml(state.currentUser.username)}</b>` : `<span style="color:var(--text-faint); font-size:14px;">Entre para escrever</span>`}
    </div>
    <textarea class="composer-textarea" id="composerText-${mode}" placeholder="${placeholder}" maxlength="480"></textarea>
    <div class="style-picker">
      <div class="style-group">
        <label>Fonte</label>
        <div class="font-row" id="fontRow-${mode}">
          ${STYLE_FONTS.map(f=>`<button class="font-opt ${styleRef.font===f.id?'active':''}" data-font="${f.id}" style="font-family:${f.family}">${f.label}</button>`).join('')}
        </div>
      </div>
      <div class="style-group">
        <label>Estilo do cartão</label>
        <div class="bg-row" id="bgRow-${mode}">
          ${STYLE_COLORS.map(c=>`<button class="bg-opt ${styleRef.color===c.id?'active':''}" data-color="${c.id}" style="background:${c.bg}" aria-label="Estilo ${c.id}"></button>`).join('')}
        </div>
      </div>
    </div>
    <div class="composer-actions">
      <span class="composer-hint" id="composerHint-${mode}">Filtro de linguagem ativo · publicações passam por moderação</span>
      <button class="btn btn-coral" id="composerSubmit-${mode}">${btnLabel}</button>
    </div>
  </div>`;
}
function wireComposer(mode){
  const styleRef = mode==='myphrases' ? state.myPhraseStyle : state.composerStyle;
  document.getElementById('fontRow-'+mode).querySelectorAll('.font-opt').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      styleRef.font = btn.dataset.font;
      btn.parentElement.querySelectorAll('.font-opt').forEach(b=>b.classList.toggle('active', b===btn));
      document.getElementById('composerText-'+mode).style.fontFamily = STYLE_FONTS.find(f=>f.id===btn.dataset.font).family;
    });
  });
  document.getElementById('bgRow-'+mode).querySelectorAll('.bg-opt').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      styleRef.color = btn.dataset.color;
      btn.parentElement.querySelectorAll('.bg-opt').forEach(b=>b.classList.toggle('active', b===btn));
    });
  });
  const submitBtn = document.getElementById('composerSubmit-'+mode);
  submitBtn.addEventListener('click', ()=>{
    requireAuth(()=>{
      const ta = document.getElementById('composerText-'+mode);
      const text = ta.value.trim();
      if(!text){ toast('Escreva algo antes de salvar.'); return; }
      if(mode==='myphrases'){ submitMyPhrase(text); }
      else{ submitCommunityPost(text); }
      ta.value='';
    }, mode==='myphrases' ? 'Crie sua conta para guardar frases só para você.' : 'Crie sua conta para publicar na comunidade.');
  });
}
function renderComposerInto(containerId, mode){
  const el = document.getElementById(containerId);
  el.innerHTML = composerHTML(mode);
  wireComposer(mode);
}

/* ---------------- publicar na comunidade ---------------- */
async function submitCommunityPost(text){
  if(containsBadWords(text)){
    toast('Sua publicação contém linguagem imprópria e não foi enviada. Por favor, revise o texto.', 4200);
    return;
  }
  const post = {
    id: uid('post'),
    authorEmail: state.currentUser.email,
    authorUsername: state.currentUser.username,
    text,
    font: state.composerStyle.font,
    color: state.composerStyle.color,
    createdAt: Date.now(),
    likes: [],
    comments: [],
    reports: [],
    hidden: false,
  };
  state.communityPosts.unshift(post);
  if(state.communityPosts.length>200) state.communityPosts.length=200;
  await saveCommunityPosts();
  toast('Publicado na comunidade');
  renderCommunityView();
}
async function saveCommunityPosts(){
  await dbSet('feed:posts', state.communityPosts, true);
}
async function loadCommunityPosts(){
  const posts = await dbGet('feed:posts', true);
  state.communityPosts = posts || [];
  if(!posts){ await seedCommunityIfNeeded(); }
}
async function seedCommunityIfNeeded(){
  const seeded = await dbGet('seeded:v1', true);
  if(seeded) return;
  const seedPosts = [
    { text:'Hoje escolhi recomeçar. Não porque foi fácil ontem, mas porque ainda acredito no que estou construindo.', authorUsername:'marina_sp', color:'jade', font:'body' },
    { text:'Aprendi que pedir ajuda não é fraqueza — é a coragem de admitir que ninguém chega a lugar nenhum sozinho.', authorUsername:'joao.forte', color:'sky', font:'display' },
    { text:'Gratidão de hoje: acordar, respirar fundo e lembrar que já superei 100% dos meus dias difíceis até agora.', authorUsername:'luztotal', color:'marigold', font:'hand' },
  ];
  const now = Date.now();
  state.communityPosts = seedPosts.map((p,i)=>({
    id: uid('post'), authorEmail: 'seed_'+i+'@memotiva.app', authorUsername:p.authorUsername,
    text:p.text, font:p.font, color:p.color, createdAt: now - (i+1)*3600*1000*7,
    likes:[], comments:[], reports:[], hidden:false,
  }));
  await saveCommunityPosts();
  await dbSet('seeded:v1', true, true);
}

/* ---------------- ações do feed ---------------- */
async function toggleLikePost(postId){
  const post = state.communityPosts.find(p=>p.id===postId);
  if(!post) return;
  const email = state.currentUser.email;
  const i = post.likes.indexOf(email);
  if(i>-1) post.likes.splice(i,1); else post.likes.push(email);
  await saveCommunityPosts();
  renderCommunityView();
}
async function addComment(postId, text){
  if(!text.trim()) return;
  if(containsBadWords(text)){ toast('Comentário bloqueado: linguagem imprópria.', 3600); return; }
  const post = state.communityPosts.find(p=>p.id===postId);
  if(!post) return;
  post.comments.push({ id:uid('c'), username: state.currentUser.username, text: text.trim(), createdAt: Date.now() });
  await saveCommunityPosts();
  renderCommunityView();
}
async function toggleFollow(username){
  const i = state.following.indexOf(username);
  if(i>-1){ state.following.splice(i,1); toast('Deixou de seguir @'+username); }
  else{ state.following.push(username); toast('Agora você segue @'+username); }
  await dbSet('following:'+state.currentUser.email, state.following, false);
  renderCommunityView();
}
async function reportPost(postId){
  const post = state.communityPosts.find(p=>p.id===postId);
  if(!post) return;
  const email = state.currentUser.email;
  if(post.reports.includes(email)){ toast('Você já denunciou esta publicação.'); return; }
  post.reports.push(email);
  if(post.reports.length>=3) post.hidden = true;
  await saveCommunityPosts();
  toast('Denúncia enviada. Obrigado por ajudar a manter a comunidade segura.');
  renderCommunityView();
}
async function sharePost(post){
  const shareText = `"${post.text}" — via MeMotiva`;
  if(navigator.share){
    try{ await navigator.share({ text: shareText }); return; }catch(e){ /* usuário cancelou */ return; }
  }
  try{
    await navigator.clipboard.writeText(shareText);
    toast('Texto copiado para compartilhar');
  }catch(e){ toast('Não foi possível copiar automaticamente.'); }
}
async function togglePostFavorite(postId){
  const pos = state.favorites.findIndex(f=>f.type==='post' && f.id===postId);
  if(pos>-1){ state.favorites.splice(pos,1); toast('Removida dos favoritos'); }
  else{ state.favorites.push({type:'post', id:postId}); toast('Salva nos favoritos'); }
  await saveFavorites();
  renderCommunityView();
}

/* ---------------- render do post ---------------- */
function postCardHTML(post){
  const styleColor = STYLE_COLORS.find(c=>c.id===post.color) || STYLE_COLORS[0];
  const font = STYLE_FONTS.find(f=>f.id===post.font) || STYLE_FONTS[0];
  const liked = state.currentUser && post.likes.includes(state.currentUser.email);
  const saved = state.favorites.some(f=>f.type==='post' && f.id===post.id);
  const isMe = state.currentUser && post.authorEmail===state.currentUser.email;
  const isFollowing = state.following.includes(post.authorUsername);
  return `
  <article class="post-card reveal in-view" data-post-id="${post.id}">
    <div class="post-head">
      <div class="post-avatar" style="background:${colorForName(post.authorUsername)}">${initials(post.authorUsername)}</div>
      <div class="post-meta">
        <div class="post-username">@${escapeHtml(post.authorUsername)}</div>
        <div class="post-time">${timeAgo(post.createdAt)}</div>
      </div>
      ${!isMe ? `<button class="btn btn-sm ${isFollowing?'btn-ghost':'btn-outline'} follow-btn" data-follow="${post.authorUsername}">${isFollowing?'Seguindo':'Seguir'}</button>` : ''}
    </div>
    <div class="post-content" data-style="${styleColor.id}">
      <p class="post-text" style="font-family:${font.family};">${escapeHtml(post.text)}</p>
    </div>
    <div class="post-actions">
      <button class="action-btn ${liked?'liked':''}" data-like="${post.id}">
        <svg viewBox="0 0 24 24" fill="${liked?'currentColor':'none'}" stroke="currentColor" stroke-width="2" stroke-linejoin="round"><path d="M12 21s-7.5-4.7-10.2-9.1C.2 9 1 5.4 4.2 4.1 6.7 3 9.3 4 12 7c2.7-3 5.3-4 7.8-2.9 3.2 1.3 4 4.9 2.4 7.8C19.5 16.3 12 21 12 21Z"/></svg>
        ${post.likes.length||''}
      </button>
      <button class="action-btn" data-comment-toggle="${post.id}">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"><path d="M21 11.5a8.4 8.4 0 0 1-8.9 8.4 9 9 0 0 1-3.4-.7L3 21l1.8-5.4a8.4 8.4 0 0 1-.8-3.6A8.4 8.4 0 0 1 12.9 3a8.5 8.5 0 0 1 8.1 8.5Z"/></svg>
        ${post.comments.length||''}
      </button>
      <button class="action-btn" data-share="${post.id}">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8.6 10.6 6.8-3.8M8.6 13.4l6.8 3.8"/></svg>
      </button>
      <button class="action-btn ${saved?'saved':''}" data-save-post="${post.id}">
        <svg viewBox="0 0 24 24" fill="${saved?'currentColor':'none'}" stroke="currentColor" stroke-width="2" stroke-linejoin="round"><path d="M6 3h12a1 1 0 0 1 1 1v17l-7-4-7 4V4a1 1 0 0 1 1-1Z"/></svg>
      </button>
      <button class="action-btn report-btn action-spacer" data-report="${post.id}" aria-label="Denunciar" title="Denunciar conteúdo">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 15V4l1.5-1 2 1.5h9L15 6l3-2v10l-2 1.5h-9L5.5 14 4 15Z"/><path d="M4 15v6"/></svg>
      </button>
    </div>
    <div class="comment-section hidden" id="comments-${post.id}">
      <div class="comment-list">
        ${post.comments.map(c=>`<div class="comment">
            <div class="comment-avatar" style="background:${colorForName(c.username)}; display:flex;align-items:center;justify-content:center;color:#fff;font-size:10px;font-weight:800;">${initials(c.username)}</div>
            <div><b>@${escapeHtml(c.username)}</b> <span style="color:var(--text-soft)">${escapeHtml(c.text)}</span></div>
          </div>`).join('') || `<p style="font-size:13px;color:var(--text-faint);">Nenhum comentário ainda.</p>`}
      </div>
      ${state.currentUser ? `<div class="comment-input-row">
        <input type="text" class="comment-input" id="commentInput-${post.id}" placeholder="Escreva um comentário…" maxlength="220">
        <button class="btn-icon" data-comment-send="${post.id}" aria-label="Enviar comentário">
          <svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m3 20 18-8L3 4v6l13 2-13 2v6Z"/></svg>
        </button>
      </div>` : ''}
    </div>
  </article>`;
}
function attachPostEvents(container){
  container.querySelectorAll('[data-like]').forEach(b=>b.addEventListener('click', ()=>requireAuth(()=>toggleLikePost(b.dataset.like), 'Crie sua conta para curtir publicações.')));
  container.querySelectorAll('[data-save-post]').forEach(b=>b.addEventListener('click', ()=>requireAuth(()=>togglePostFavorite(b.dataset.savePost), 'Crie sua conta para salvar nos favoritos.')));
  container.querySelectorAll('[data-follow]').forEach(b=>b.addEventListener('click', ()=>requireAuth(()=>toggleFollow(b.dataset.follow), 'Crie sua conta para seguir outras pessoas.')));
  container.querySelectorAll('[data-report]').forEach(b=>b.addEventListener('click', ()=>requireAuth(()=>reportPost(b.dataset.report), 'Crie sua conta para denunciar conteúdo.')));
  container.querySelectorAll('[data-share]').forEach(b=>b.addEventListener('click', ()=>{
    const post = state.communityPosts.find(p=>p.id===b.dataset.share);
    if(post) sharePost(post);
  }));
  container.querySelectorAll('[data-comment-toggle]').forEach(b=>b.addEventListener('click', ()=>{
    requireAuth(()=>{
      document.getElementById('comments-'+b.dataset.commentToggle).classList.toggle('hidden');
    }, 'Crie sua conta para comentar.');
  }));
  container.querySelectorAll('[data-comment-send]').forEach(b=>b.addEventListener('click', ()=>{
    const id = b.dataset.commentSend;
    const input = document.getElementById('commentInput-'+id);
    addComment(id, input.value);
    input.value='';
  }));
  container.querySelectorAll('.comment-input').forEach(inp=>{
    inp.addEventListener('keydown', e=>{
      if(e.key==='Enter'){ const id = inp.id.replace('commentInput-',''); addComment(id, inp.value); inp.value=''; }
    });
  });
}
function renderCommunityView(){
  renderComposerInto('composerSlot', 'community');
  let posts = state.communityPosts.filter(p=>!p.hidden);
  if(state.feedFilter==='seguindo') posts = posts.filter(p=>state.following.includes(p.authorUsername));
  if(state.feedFilter==='minhas') posts = state.currentUser ? posts.filter(p=>p.authorEmail===state.currentUser.email) : [];
  const feedEl = document.getElementById('communityFeed');
  const emptyEl = document.getElementById('feedEmpty');
  if(posts.length===0){ feedEl.innerHTML=''; emptyEl.classList.remove('hidden'); }
  else{ emptyEl.classList.add('hidden'); feedEl.innerHTML = posts.map(postCardHTML).join(''); attachPostEvents(feedEl); }
}
document.querySelectorAll('#feedFilterChips .chip').forEach(chip=>{
  chip.addEventListener('click', ()=>{
    state.feedFilter = chip.dataset.feedFilter;
    document.querySelectorAll('#feedFilterChips .chip').forEach(c=>c.classList.toggle('active', c===chip));
    if(chip.dataset.feedFilter==='seguindo' || chip.dataset.feedFilter==='minhas'){
      requireAuth(renderCommunityView, 'Crie sua conta para ver esta aba.');
    } else renderCommunityView();
  });
});
function renderCommunityPreview(){
  const el = document.getElementById('communityPreview');
  const posts = state.communityPosts.filter(p=>!p.hidden).slice(0,2);
  el.innerHTML = posts.map(postCardHTML).join('');
  attachPostEvents(el);
}

/* ================================================================
   MINHAS FRASES (privado — não publicado)
   ================================================================ */
async function submitMyPhrase(text){
  const phrase = {
    id: uid('mp'), text,
    font: state.myPhraseStyle.font, color: state.myPhraseStyle.color,
    createdAt: Date.now(),
  };
  state.myPhrases.unshift(phrase);
  await saveMyPhrases();
  toast('Salva em Minhas Frases');
  if(state.view==='perfil') renderPerfil();
}
async function deleteMyPhrase(id){
  state.myPhrases = state.myPhrases.filter(p=>p.id!==id);
  await saveMyPhrases();
  renderPerfil();
}
async function saveMyPhrases(){
  if(!state.currentUser) return;
  await dbSet('myphrases:'+state.currentUser.email, state.myPhrases, false);
}
function myPhraseCardHTML(p){
  const styleColor = STYLE_COLORS.find(c=>c.id===p.color) || STYLE_COLORS[0];
  const font = STYLE_FONTS.find(f=>f.id===p.font) || STYLE_FONTS[0];
  return `<div class="phrase-card reveal in-view" data-style="${styleColor.id}">
    <button class="btn-icon del-btn btn-sm" style="width:32px;height:32px;" data-del-phrase="${p.id}" aria-label="Excluir">
      <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M4 7h16M9 7V5a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2m-8 0 1 13a1 1 0 0 0 1 1h6a1 1 0 0 0 1-1l1-13"/></svg>
    </button>
    <p style="font-family:${font.family}; font-size:16px; line-height:1.5; padding-right:24px;">${escapeHtml(p.text)}</p>
    <p style="font-size:11.5px; color:var(--text-faint); margin-top:12px; font-weight:600;">${new Date(p.createdAt).toLocaleDateString('pt-BR')}</p>
  </div>`;
}

/* ================================================================
   FAVORITOS
   ================================================================ */
function favoritesHTML(){
  if(state.favorites.length===0){
    return `<div class="empty-state">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M12 21s-7.5-4.7-10.2-9.1C.2 9 1 5.4 4.2 4.1 6.7 3 9.3 4 12 7c2.7-3 5.3-4 7.8-2.9 3.2 1.3 4 4.9 2.4 7.8C19.5 16.3 12 21 12 21Z"/></svg>
      <h3>Sua lista de favoritos está vazia</h3>
      <p>Toque no coração de qualquer frase ou publicação para guardá-la aqui.</p>
    </div>`;
  }
  const quoteFavs = state.favorites.filter(f=>f.type==='quote').map(f=>{ const i = QUOTE_POR_QID[f.qid]; return {q:QUOTES[i], idx:i}; }).filter(x=>x.q);
  const postFavs = state.favorites.filter(f=>f.type==='post').map(f=>state.communityPosts.find(p=>p.id===f.id)).filter(Boolean);
  let html = '';
  if(quoteFavs.length){
    html += `<h3 style="font-family:var(--font-display); font-size:18px; margin:22px 0 14px;">Frases de autores</h3><div class="quote-grid">${quoteFavs.map(({q,idx})=>quoteCardHTML(q,idx)).join('')}</div>`;
  }
  if(postFavs.length){
    html += `<h3 style="font-family:var(--font-display); font-size:18px; margin:30px 0 14px;">Publicações da comunidade</h3><div class="feed">${postFavs.map(postCardHTML).join('')}</div>`;
  }
  return html;
}

/* ================================================================
   PERFIL (visão geral · favoritos · minhas frases)
   ================================================================ */
let profileTab = 'overview';
function renderPerfil(){
  const el = document.getElementById('perfilContent');
  if(!state.currentUser){
    el.innerHTML = `<div class="empty-state">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M20 21a8 8 0 1 0-16 0"/><circle cx="12" cy="7" r="4"/></svg>
      <h3>Você ainda não entrou</h3>
      <p>Crie uma conta gratuita para salvar favoritos, escrever suas frases privadas e participar da comunidade.</p>
      <button class="btn btn-coral" style="margin-top:18px;" id="perfilLoginBtn">Entrar ou criar conta</button>
    </div>`;
    document.getElementById('perfilLoginBtn').addEventListener('click', ()=>openAuthModal());
    return;
  }
  const u = state.currentUser;
  el.innerHTML = `
    <div class="profile-head">
      <div class="profile-avatar" style="background:${colorForName(u.username)}">${initials(u.username)}</div>
      <div>
        <h2 style="font-family:var(--font-display); font-size:24px;">${escapeHtml(u.username)}</h2>
        <p style="color:var(--text-soft); font-size:14px;">${escapeHtml(u.email)}</p>
        <div class="profile-stats">
          <span><b>${state.communityPosts.filter(p=>p.authorEmail===u.email).length}</b> <span style="color:var(--text-faint);font-size:12.5px;">publicações</span></span>
          <span><b>${state.favorites.length}</b> <span style="color:var(--text-faint);font-size:12.5px;">favoritos</span></span>
          <span><b>${state.following.length}</b> <span style="color:var(--text-faint);font-size:12.5px;">seguindo</span></span>
        </div>
      </div>
      <button class="btn btn-outline btn-sm" id="logoutBtn" style="margin-left:auto;">Sair</button>
    </div>
    <div class="profile-tabs">
      <button class="profile-tab ${profileTab==='overview'?'active':''}" data-tab="overview">Minhas Frases</button>
      <button class="profile-tab ${profileTab==='favorites'?'active':''}" data-tab="favorites">Favoritos</button>
    </div>
    <div id="profileTabContent"></div>
  `;
  document.getElementById('logoutBtn').addEventListener('click', logout);
  el.querySelectorAll('.profile-tab').forEach(t=>t.addEventListener('click', ()=>{ profileTab=t.dataset.tab; renderPerfil(); }));
  const tabContent = document.getElementById('profileTabContent');
  if(profileTab==='favorites'){
    tabContent.innerHTML = favoritesHTML();
    tabContent.querySelectorAll('[data-fav-quote]').forEach(btn=>btn.addEventListener('click', ()=>toggleFavoriteQuote(Number(btn.dataset.favQuote)).then(renderPerfil)));
    attachPostEvents(tabContent);
  }else{
    tabContent.innerHTML = `<div id="myPhrasesComposer"></div>
      <div class="phrase-grid" id="myPhrasesGrid">${state.myPhrases.map(myPhraseCardHTML).join('') || '<p style="color:var(--text-faint);grid-column:1/-1;">Nenhuma frase salva ainda.</p>'}</div>`;
    renderComposerInto('myPhrasesComposer', 'myphrases');
    tabContent.querySelectorAll('[data-del-phrase]').forEach(btn=>btn.addEventListener('click', ()=>deleteMyPhrase(btn.dataset.delPhrase)));
  }
}

/* ================================================================
   AUTENTICAÇÃO
   Protótipo funcional: cadastro/login validam contra registros
   guardados no armazenamento do artifact, com a senha convertida
   em hash (SHA-256) antes de ser salva — nunca em texto puro.
   Isto NÃO substitui um backend de produção com verificação de
   e-mail, limite de tentativas etc., mas já não guarda senha crua.
   ================================================================ */
function isValidEmail(email){ return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email); }

function openAuthModal(message){
  document.getElementById('authModalSub').textContent = message || 'Entre para curtir, comentar e guardar suas frases.';
  document.getElementById('authModal').classList.add('show');
  document.getElementById('scrim').classList.add('show');
}
function closeAuthModal(){
  document.getElementById('authModal').classList.remove('show');
  document.getElementById('scrim').classList.remove('show');
  document.getElementById('loginError').textContent='';
  document.getElementById('registerError').textContent='';
  state.pendingAction = null;
}
function switchAuthTab(tab){
  const isLogin = tab==='login';
  document.getElementById('tabLogin').classList.toggle('active', isLogin);
  document.getElementById('tabRegister').classList.toggle('active', !isLogin);
  document.getElementById('loginForm').classList.toggle('hidden', !isLogin);
  document.getElementById('registerForm').classList.toggle('hidden', isLogin);
  document.getElementById('authModalTitle').textContent = isLogin ? 'Bem-vinda(o) de volta' : 'Criar sua conta gratuita';
  document.getElementById('authSwitchLine').innerHTML = isLogin
    ? `Ainda não tem conta? <button id="switchToRegister">Criar conta</button>`
    : `Já tem conta? <button id="switchToLogin">Entrar</button>`;
  wireAuthSwitchLine();
}
function wireAuthSwitchLine(){
  const r = document.getElementById('switchToRegister');
  const l = document.getElementById('switchToLogin');
  if(r) r.addEventListener('click', ()=>switchAuthTab('register'));
  if(l) l.addEventListener('click', ()=>switchAuthTab('login'));
}
document.getElementById('tabLogin').addEventListener('click', ()=>switchAuthTab('login'));
document.getElementById('tabRegister').addEventListener('click', ()=>switchAuthTab('register'));
wireAuthSwitchLine();
document.getElementById('closeAuthModal').addEventListener('click', closeAuthModal);

function requireAuth(callback, message){
  if(state.currentUser){ callback(); return; }
  state.pendingAction = callback;
  openAuthModal(message);
}

async function handleLogin(email, password){
  const errEl = document.getElementById('loginError');
  errEl.textContent='';
  email = email.trim().toLowerCase();
  const user = await dbGet('user:'+email, true);
  if(!user){ errEl.textContent = 'Não encontramos uma conta com este e-mail.'; return; }
  const hash = await sha256(password);
  if(hash !== user.passwordHash){ errEl.textContent = 'Senha incorreta. Tente novamente.'; return; }
  await completeLogin({ email, username: user.username });
}
async function handleRegister(username, email, password, password2){
  const errEl = document.getElementById('registerError');
  errEl.textContent='';
  username = username.trim();
  email = email.trim().toLowerCase();
  if(username.length<3){ errEl.textContent='Escolha um nome de usuário com pelo menos 3 caracteres.'; return; }
  if(!isValidEmail(email)){ errEl.textContent='Digite um e-mail válido.'; return; }
  if(password.length<6){ errEl.textContent='A senha precisa ter pelo menos 6 caracteres.'; return; }
  if(password!==password2){ errEl.textContent='As senhas não coincidem.'; return; }
  const existing = await dbGet('user:'+email, true);
  if(existing){ errEl.textContent='Já existe uma conta com este e-mail. Tente entrar.'; return; }
  const usernameTaken = await dbGet('username:'+username.toLowerCase(), true);
  if(usernameTaken){ errEl.textContent='Este nome de usuário já está em uso.'; return; }
  const passwordHash = await sha256(password);
  await dbSet('user:'+email, { username, email, passwordHash, createdAt: Date.now() }, true);
  await dbSet('username:'+username.toLowerCase(), email, true);
  toast('Conta criada com sucesso! Bem-vinda(o)');
  await completeLogin({ email, username });
}
async function completeLogin(user){
  state.currentUser = user;
  await dbSet('session', user, false);
  await loadUserData();
  closeAuthModal();
  renderHeaderAuthArea();
  renderAuthDependentUI();
  toast(`Olá, ${user.username}!`);
  if(state.pendingAction){ const fn = state.pendingAction; state.pendingAction=null; fn(); }
}
async function logout(){
  state.currentUser = null;
  state.favorites = []; state.myPhrases = []; state.following = [];
  await dbSet('session', null, false);
  renderHeaderAuthArea();
  renderAuthDependentUI();
  navigateTo('home');
  toast('Você saiu da sua conta.');
}
async function loadUserData(){
  if(!state.currentUser) return;
  const email = state.currentUser.email;
  state.favorites = normalizarFavoritos(await dbGet('favorites:'+email, false));
  state.myPhrases = (await dbGet('myphrases:'+email, false)) || [];
  state.following = (await dbGet('following:'+email, false)) || [];
}
async function loadSession(){
  const session = await dbGet('session', false);
  if(session && session.email){
    state.currentUser = session;
    await loadUserData();
  }
}
function renderHeaderAuthArea(){
  const el = document.getElementById('headerAuthArea');
  if(state.currentUser){
    el.innerHTML = `<button class="user-chip" data-nav="perfil">
      <span class="mini-avatar" style="background:${colorForName(state.currentUser.username)}; display:flex; align-items:center; justify-content:center; color:#fff; font-weight:800; font-size:11px; border-radius:50%;">${initials(state.currentUser.username)}</span>
      ${escapeHtml(state.currentUser.username)}
    </button>`;
    el.querySelector('[data-nav]').addEventListener('click', ()=>navigateTo('perfil'));
  }else{
    el.innerHTML = `<button class="btn btn-coral btn-sm" id="headerLoginBtn">Entrar</button>`;
    document.getElementById('headerLoginBtn').addEventListener('click', ()=>openAuthModal());
  }
}
function renderAuthDependentUI(){
  // Re-renderiza qualquer parte da tela que dependa de estar logado
  if(state.view==='comunidade') renderCommunityView();
  if(state.view==='explorar') renderExploreResults();
  if(state.view==='perfil') renderPerfil();
  renderQuoteOfDay();
}

