const DISCOVER_BATCH = 12;
let discoverQueue = [], discoverFilter = 'all';

function discoverList(){
  return STORIES.filter(s => discoverFilter==='all' || (s.profiles||[]).includes(discoverFilter));
}
function discoverCardHTML(s){
  const tags = (s.profiles||[]).slice(0,2).map(p=>profileById(p)).filter(Boolean);
  return `
  <article class="discover-card reveal" data-discover="${s.id}" role="button" tabindex="0"
           aria-label="Ver biografia de ${escapeHtml(s.author)}">
    <div class="discover-photo">
      ${photoImgHTML(s.author,'card',420)}
      <div class="avatar-fallback" style="display:none; background:${colorForName(s.author)};">${initials(s.author)}</div>
      <h3 class="discover-name">${escapeHtml(s.author)}</h3>
    </div>
    <div class="discover-body">
      ${s.role ? `<span class="discover-role">${escapeHtml(s.role)}</span>` : ''}
      <p class="discover-why">${escapeHtml(s.why || s.excerpt)}</p>
      ${tags.length ? `<div class="discover-tags">${tags.map(t=>`<span class="discover-tag">${escapeHtml(t.name)}</span>`).join('')}</div>` : ''}
      <span class="discover-cta">Ler a história
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="m9 5 7 7-7 7"/></svg>
      </span>
    </div>
  </article>`;
}
function appendDiscoverBatch(){
  const grid = document.getElementById('discoverGrid');
  if(!grid || !discoverQueue.length) return;
  const batch = discoverQueue.splice(0, DISCOVER_BATCH);
  const holder = document.createElement('div');
  const frag = document.createDocumentFragment();
  batch.forEach(s=>{
    holder.innerHTML = discoverCardHTML(s);
    frag.appendChild(holder.firstElementChild);
  });
  grid.appendChild(frag);
  wireDiscoverCards(grid);
  requestAnimationFrame(observeReveals);
}
function wireDiscoverCards(scope){
  scope.querySelectorAll('[data-discover]:not([data-wired])').forEach(card=>{
    card.dataset.wired = '1';
    const open = ()=>openBiography(card.dataset.discover);
    card.addEventListener('click', open);
    card.addEventListener('keydown', e=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); open(); } });
  });
}
function renderDiscoverFilters(){
  const row = document.getElementById('discoverFilterRow');
  if(!row) return;
  const avail = PROFILES.filter(p => STORIES.some(s=>(s.profiles||[]).includes(p.id)));
  row.innerHTML = [{id:'all',name:'Todas as pessoas'}, ...avail].map(p=>{
    const n = p.id==='all' ? STORIES.length : STORIES.filter(s=>(s.profiles||[]).includes(p.id)).length;
    return `<button class="chip ${discoverFilter===p.id?'active':''}" data-discover-filter="${p.id}">${escapeHtml(p.name)} <span style="opacity:.55">${n}</span></button>`;
  }).join('');
  row.querySelectorAll('[data-discover-filter]').forEach(b=>{
    b.addEventListener('click', ()=>{ discoverFilter = b.dataset.discoverFilter; renderDiscover(); });
  });
}
function renderDiscover(){
  const grid = document.getElementById('discoverGrid');
  if(!grid) return;
  renderDiscoverFilters();
  const list = discoverList();
  grid.innerHTML = '';
  discoverQueue = list.slice();
  const cnt = document.getElementById('discoverCount');
  if(cnt) cnt.textContent = list.length === 1 ? '1 pessoa' : `${list.length} pessoas para conhecer`;
  appendDiscoverBatch();
  fillDiscoverWhileVisible();
}
function fillDiscoverWhileVisible(){
  const view = document.getElementById('view-descubra');
  if(!view || view.classList.contains('hidden')) return;
  const sentinel = document.getElementById('discoverSentinel');
  if(!sentinel || !discoverQueue.length) return;
  const r = sentinel.getBoundingClientRect();
  if(r.top < window.innerHeight + 400){
    appendDiscoverBatch();
    requestAnimationFrame(fillDiscoverWhileVisible);
  }
}

/* ================================================================
   BIOGRAFIAS (§6 e §7) — filtros, contagem e carregamento progressivo
   ================================================================ */
const BIO_BATCH = 6;
let bioQueue = [], bioFilter = { profile:'all', origin:'all' };

function bioList(){
  return STORIES.filter(s=>{
    if(bioFilter.profile!=='all' && !(s.profiles||[]).includes(bioFilter.profile)) return false;
    if(bioFilter.origin!=='all' && s.origin !== bioFilter.origin) return false;
    return true;
  });
}
function storyCoverHTML(s){
  const base = catColor(s.cat);
  const bg = `linear-gradient(135deg, ${base}, color-mix(in srgb, ${base} 65%, black))`;
  return `<div class="story-cover" style="background:${bg};" data-open-photo="${escapeHtml(s.author)}" role="button" tabindex="0" aria-label="Ampliar fotografia de ${escapeHtml(s.author)}">
      ${photoImgHTML(s.author,'wide',600)}
      <span class="story-cover-fallback" style="display:none;">${initials(s.author)}</span>
    </div>`;
}
function storyCardHTML(s){
  const cat = catById(s.cat);
  const tags = (s.profiles||[]).map(p=>profileById(p)).filter(Boolean).slice(0,3);
  return `
  <article class="story-card reveal" data-story-id="${s.id}">
    ${storyCoverHTML(s)}
    <div class="story-body">
      <span class="story-cat">${cat?cat.name:''}</span>
      <h3 class="story-title">${escapeHtml(s.title)}</h3>
      ${tags.length ? `<div class="story-profiles">${tags.map(t=>`<span class="discover-tag">${escapeHtml(t.name)}</span>`).join('')}</div>` : ''}
      <p class="story-excerpt">${escapeHtml(s.excerpt)}</p>
      <div class="story-full-wrap hidden" data-full-for="${s.id}">
        <p class="story-full">${escapeHtml(s.text).replace(/\n\n/g,'</p><p class="story-full">')}</p>
      </div>
      <button class="story-toggle" data-story-toggle="${s.id}">Ler biografia completa ↓</button>
      <div class="story-audio">
        <button class="play-btn" data-story-play="${s.id}" aria-label="Reproduzir narração">${playIconSVG()}</button>
        <select class="voice-select" data-voice-for="${s.id}">
          <option value="female">Voz feminina</option>
          <option value="male">Voz masculina</option>
        </select>
        <span class="audio-status" data-status-for="${s.id}">Toque para ouvir</span>
      </div>
    </div>
  </article>`;
}
function wireStoryCards(scope){
  scope.querySelectorAll('[data-story-toggle]:not([data-wired])').forEach(btn=>{
    btn.dataset.wired = '1';
    btn.addEventListener('click', ()=>{
      const card = btn.closest('.story-card');
      const box = card.querySelector('[data-full-for]');
      const isHidden = box.classList.contains('hidden');
      box.classList.toggle('hidden');
      btn.textContent = isHidden ? 'Ler menos ↑' : 'Ler biografia completa ↓';
    });
  });
  scope.querySelectorAll('[data-story-play]:not([data-wired])').forEach(btn=>{
    btn.dataset.wired = '1';
    btn.addEventListener('click', ()=>{
      const id = btn.dataset.storyPlay;
      const card = btn.closest('.story-card');
      const statusEl = card.querySelector('[data-status-for]');
      const voiceSel = card.querySelector('[data-voice-for]');
      const story = STORIES.find(s=>s.id===id);
      toggleStoryAudio(id, `${story.title}. ${story.text}`, btn, statusEl, voiceSel);
    });
  });
  scope.querySelectorAll('.story-cover[data-open-photo]:not([data-wired])').forEach(el=>{
    el.dataset.wired = '1';
    const go = (e)=>{ e.stopPropagation(); openPhotoModal(el.dataset.openPhoto); };
    el.addEventListener('click', go);
    el.addEventListener('keydown', e=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); go(e); } });
  });
}
/* mantém a assinatura antiga usada na prévia da Início */
function renderStoriesGrid(containerId, list){
  const el = document.getElementById(containerId);
  if(!el) return;
  el.innerHTML = (list||STORIES).map(s=>storyCardHTML(s)).join('');
  wireStoryCards(el);
  requestAnimationFrame(observeReveals);
}
function appendBioBatch(){
  const grid = document.getElementById('storiesGrid');
  if(!grid || !bioQueue.length) return;
  const batch = bioQueue.splice(0, BIO_BATCH);
  const holder = document.createElement('div');
  const frag = document.createDocumentFragment();
  batch.forEach(s=>{ holder.innerHTML = storyCardHTML(s); frag.appendChild(holder.firstElementChild); });
  grid.appendChild(frag);
  wireStoryCards(grid);
  requestAnimationFrame(observeReveals);
}
function fillBioWhileVisible(){
  const view = document.getElementById('view-historias');
  if(!view || view.classList.contains('hidden')) return;
  const sentinel = document.getElementById('bioSentinel');
  if(!sentinel || !bioQueue.length) return;
  const r = sentinel.getBoundingClientRect();
  if(r.top < window.innerHeight + 400){
    appendBioBatch();
    requestAnimationFrame(fillBioWhileVisible);
  }
}
function renderBioFilters(){
  const pRow = document.getElementById('bioProfileRow');
  const oRow = document.getElementById('bioOriginRow');
  if(!pRow || !oRow) return;
  const availP = PROFILES.filter(p => STORIES.some(s=>(s.profiles||[]).includes(p.id)));
  pRow.innerHTML = [{id:'all',name:'Todas'}, ...availP].map(p=>
    `<button class="chip ${bioFilter.profile===p.id?'active':''}" data-bio-profile="${p.id}">${escapeHtml(p.name)}</button>`).join('');
  /* origem só existe se houver material suficiente (§6) */
  const availO = ORIGINS.filter(o => STORIES.filter(s=>s.origin===o.id).length >= 2);
  oRow.parentElement.classList.toggle('hidden', availO.length < 2);
  oRow.innerHTML = [{id:'all',name:'Todas'}, ...availO].map(o=>
    `<button class="chip ${bioFilter.origin===o.id?'active':''}" data-bio-origin="${o.id}">${escapeHtml(o.name)}</button>`).join('');
  pRow.querySelectorAll('[data-bio-profile]').forEach(b=>b.addEventListener('click', ()=>{ bioFilter.profile=b.dataset.bioProfile; renderBiographies(); }));
  oRow.querySelectorAll('[data-bio-origin]').forEach(b=>b.addEventListener('click', ()=>{ bioFilter.origin=b.dataset.bioOrigin; renderBiographies(); }));
  updateFilterArrows();
}
function renderBiographies(){
  const grid = document.getElementById('storiesGrid');
  if(!grid) return;
  renderBioFilters();
  const list = bioList();
  grid.innerHTML = '';
  bioQueue = list.slice();
  const cnt = document.getElementById('bioCount');
  if(cnt) cnt.textContent = list.length === 1 ? '1 biografia' : `${list.length} biografias`;
  const empty = document.getElementById('bioEmpty');
  if(empty) empty.classList.toggle('hidden', list.length > 0);
  appendBioBatch();
  fillBioWhileVisible();
}
function openBiography(id){
  navigateTo('historias');
  bioFilter = { profile:'all', origin:'all' };
  renderBiographies();
  /* garante que o cartão-alvo esteja carregado antes de rolar até ele */
  let guard = 0;
  (function ensure(){
    let card = document.querySelector(`[data-story-id="${id}"]`);
    if(!card && bioQueue.length && guard++ < 60){ appendBioBatch(); return requestAnimationFrame(ensure); }
    if(!card) return;
    const btn = card.querySelector('[data-story-toggle]');
    const box = card.querySelector('[data-full-for]');
    if(box && box.classList.contains('hidden')){ box.classList.remove('hidden'); if(btn) btn.textContent = 'Ler menos ↑'; }
    const y = card.getBoundingClientRect().top + window.scrollY - 96;
    window.scrollTo({ top:y, behavior: prefersReducedMotion() ? 'auto' : 'smooth' });
  })();
}

/* ---- setas das faixas de filtro no desktop (mesma lógica dos chips) ---- */
function updateFilterArrows(){
  document.querySelectorAll('.filter-bar').forEach(bar=>{
    const row = bar.querySelector('.filter-row');
    const prev = bar.querySelector('[data-farrow="prev"]');
    const next = bar.querySelector('[data-farrow="next"]');
    if(!row || !prev || !next) return;
    const max = row.scrollWidth - row.clientWidth - 2;
    const overflow = max > 0;
    prev.classList.toggle('hidden', !overflow || row.scrollLeft <= 2);
    next.classList.toggle('hidden', !overflow || row.scrollLeft >= max);
  });
}
function wireFilterArrows(){
  document.querySelectorAll('.filter-bar').forEach(bar=>{
    const row = bar.querySelector('.filter-row');
    if(!row || row.dataset.wired) return;
    row.dataset.wired = '1';
    bar.querySelectorAll('[data-farrow]').forEach(btn=>{
      btn.addEventListener('click', ()=>{
        const step = Math.max(180, Math.round(row.clientWidth * 0.7));
        row.scrollBy({ left: btn.dataset.farrow==='next' ? step : -step, behavior: prefersReducedMotion()?'auto':'smooth' });
      });
    });
    row.addEventListener('scroll', ()=>requestAnimationFrame(updateFilterArrows), { passive:true });
    /* roda do mouse rola a faixa na horizontal, sem sequestrar a página */
    row.addEventListener('wheel', (e)=>{
      if(Math.abs(e.deltaY) <= Math.abs(e.deltaX)) return;
      const max = row.scrollWidth - row.clientWidth;
      if(max <= 0) return;
      const atStart = row.scrollLeft <= 0 && e.deltaY < 0;
      const atEnd = row.scrollLeft >= max - 1 && e.deltaY > 0;
      if(atStart || atEnd) return;
      e.preventDefault();
      row.scrollLeft += e.deltaY;
    }, { passive:false });
  });
}

/* ================================================================
   NAVEGAÇÃO — inclui a nova view Descubra
   ================================================================ */
function navigateTo(view){
  state.view = view;
  document.querySelectorAll('.view').forEach(el=>{
    el.classList.toggle('hidden', el.dataset.view !== view);
  });
  document.querySelectorAll('[data-nav]').forEach(el=>{
    el.classList.toggle('active', el.dataset.nav === view);
  });
  window.scrollTo({top:0, behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto':'smooth'});
  closeMobileMenu();
  closeProfilePanel();
  if(view==='explorar') renderExplore();
  if(view==='descubra') renderDiscover();
  if(view==='historias') renderBiographies();
  if(view==='comunidade') renderCommunityView();
  if(view==='perfil') renderPerfil();
  requestAnimationFrame(()=>{ observeReveals(); wireFilterArrows(); updateFilterArrows(); });
}

/* ================================================================
   LIGAÇÕES FINAIS
   ================================================================ */
function initFase2(){
  /* filtro por atuação */
  const pfBtn = document.getElementById('profileFilterBtn');
  if(pfBtn) pfBtn.addEventListener('click', (e)=>{ e.stopPropagation(); toggleProfilePanel(); });
  document.addEventListener('click', (e)=>{
    const wrap = document.getElementById('profileFilterWrap');
    if(wrap && !wrap.contains(e.target)) closeProfilePanel();
  });
  const pfClear = document.getElementById('profileClear');
  if(pfClear) pfClear.addEventListener('click', ()=>{
    state.exploreFilter.profile = 'all';
    closeProfilePanel(); renderProfileFilter(); renderExploreResults();
  });

  /* fechar modais: X, clique no fundo, Esc */
  ['quoteExpand','photoExpand'].forEach(id=>{
    const el = document.getElementById(id);
    if(!el) return;
    el.addEventListener('click', (e)=>{ if(e.target === el){ id==='quoteExpand' ? closeQuoteModal() : closePhotoModal(); } });
  });
  document.addEventListener('keydown', (e)=>{
    if(e.key !== 'Escape') return;
    /* fecha o de cima primeiro: foto sobre frase */
    if(document.getElementById('photoExpand').classList.contains('show')) return closePhotoModal();
    if(document.getElementById('quoteExpand').classList.contains('show')) return closeQuoteModal();
    closeProfilePanel();
  });

  /* rolagem infinita das novas áreas */
  let tick = false;
  const onScroll = ()=>{
    if(tick) return;
    tick = true;
    requestAnimationFrame(()=>{
      tick = false;
      if(state.view==='descubra') fillDiscoverWhileVisible();
      if(state.view==='historias') fillBioWhileVisible();
    });
  };
  window.addEventListener('scroll', onScroll, { passive:true });
  window.addEventListener('resize', ()=>{ updateFilterArrows(); onScroll(); }, { passive:true });

  wireFilterArrows();
  updateFilterArrows();
}


