/* ================================================================
   EXIBIÇÃO HONESTA DA PROCEDÊNCIA
   A expansão do cartão passa a mostrar a fonte e, quando a frase é
   paráfrase ou está pendente de revisão, diz isso com todas as
   letras — em vez de apresentar plausibilidade como prova.
   ================================================================ */
const STATUS_ROTULO = {
  A:  { texto:'',                                    classe:'' },
  'A-':{ texto:'',                                   classe:'' },
  B:  { texto:'',                                    classe:'' },
  P:  { texto:'Paráfrase ou atribuição popular — sem fonte primária localizada.', classe:'src-alerta' },
  R:  { texto:'Atribuição corrente; fonte ainda não localizada.',                 classe:'src-alerta' },
  X:  { texto:'',                                    classe:'' },
};
function procedenciaHTML(q){
  const rot = STATUS_ROTULO[q.st] || STATUS_ROTULO.R;
  let out = '';
  if(q.src) out += `<span class="expand-src">${escapeHtml(q.src)}</span>`;
  if(rot.texto) out += `<span class="expand-src ${rot.classe}">${escapeHtml(rot.texto)}</span>`;
  if(q.autorAnterior) out += `<span class="expand-src src-alerta">Circula como frase de ${escapeHtml(q.autorAnterior)}.</span>`;
  return out;
}

function openQuoteModal(idx){
  const q = QUOTES[idx];
  if(!q) return;
  const el = document.getElementById('quoteExpand');
  const box = document.getElementById('quoteExpandBox');
  const bio = bioIdFor(q.author);
  const col = colorForName(q.author);
  box.innerHTML = `
    <button class="expand-close" id="quoteExpandClose" aria-label="Fechar frase ampliada">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><path d="M6 6l12 12M18 6L6 18"/></svg>
    </button>
    <span class="quote-card-tape" aria-hidden="true"></span>
    <div class="expand-inner">
      <span class="expand-cat">${escapeHtml(quoteCatLabel(q))}</span>
      <p class="expand-text" style="font-size:${quoteFontSize(q.text)}">&ldquo;${escapeHtml(q.text)}&rdquo;</p>
      <div class="expand-foot">
        <div class="expand-avatar" data-open-photo="${escapeHtml(q.author)}" role="button" tabindex="0" aria-label="Ampliar fotografia de ${escapeHtml(q.author)}">
          ${photoImgHTML(q.author,'card',420)}
          <div class="avatar-fallback" style="display:none; background:${col};">${initials(q.author)}</div>
        </div>
        <div class="expand-ident">
          <span class="expand-author">— ${escapeHtml(q.author)}</span>
          ${procedenciaHTML(q)}
        </div>
        ${bio ? `<button class="expand-bio-link" data-go-bio="${bio}">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2Z"/></svg>
          Saiba mais
        </button>` : ''}
      </div>
    </div>`;
  el.classList.add('show');
  el.setAttribute('aria-hidden','false');
  lockScroll();
  document.getElementById('quoteExpandClose').addEventListener('click', closeQuoteModal);
  box.querySelectorAll('[data-open-photo]').forEach(b=>{
    const go = (ev)=>{ ev.stopPropagation(); openPhotoModal(b.dataset.openPhoto); };
    b.addEventListener('click', go);
    b.addEventListener('keydown', e=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); go(e); } });
  });
  const bioBtn = box.querySelector('[data-go-bio]');
  if(bioBtn) bioBtn.addEventListener('click', ()=>{ closeQuoteModal(); openBiography(bioBtn.dataset.goBio); });
  requestAnimationFrame(()=>document.getElementById('quoteExpandClose').focus());
}


/* ================================================================
   AGRUPAMENTO DE VARIANTES — NÃO DESTRUTIVO
   ----------------------------------------------------------------
   O banco acumulou traduções diferentes da mesma passagem como se
   fossem frases distintas (Tao Te Ching 33 aparece 9 vezes, a Ética
   a Nicômaco VIII, 16). Isso enche a grade do Explorar de repetição.

   Em vez de apagar — o que seria irreversível — as variantes são
   agrupadas: uma é eleita representante e as demais ficam ocultas
   na navegação, mas continuam no banco, continuam aparecendo na
   busca e podem ser reveladas com um clique.
   ================================================================ */

/* Duas frases só são variantes uma da outra quando (a) apontam a
   mesma fonte E (b) dizem substancialmente a mesma coisa. A segunda
   condição é o que impede que dois trechos diferentes do mesmo livro
   sejam tratados como repetição. */
const _STOP = new Set(['a','o','as','os','de','da','do','das','dos','e','é','que','em','um','uma','no','na','se','por','com','para','ao','à','mais','não','nem','the','of']);
function _tokens(t){
  return new Set(t.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^a-z0-9 ]/g,' ').split(/\s+/)
    .filter(w => w.length > 2 && !_STOP.has(w))
    .map(w => w.replace(/(mente|ando|endo|indo|ava|ou|es|as|os|a|o|e)$/,'')));
}
function _similar(a, b){
  if(!a.size || !b.size) return 0;
  let inter = 0;
  a.forEach(w => { if(b.has(w)) inter++; });
  return inter / Math.min(a.size, b.size);
}
function fonteAgrupavel(src){
  if(!src) return false;
  if(/não confirmad|não identificad|não localizad|Atribuição popular|Paráfrase|paráfrase|sem fonte|sem registro|sem localização|demais obras|e entrevistas|e discursos|e palestras|e demais/i.test(src)) return false;
  return true;
}

const VARIANTES = { grupos:0, ocultas:0 };

(function agruparVariantes(){
  const porFonte = new Map();
  QUOTES.forEach((q, i)=>{
    if(!fonteAgrupavel(q.src)) return;
    const k = canonAuthor(q.author) + ' ⟨' + q.src + '⟩';
    if(!porFonte.has(k)) porFonte.set(k, []);
    porFonte.get(k).push(i);
  });

  porFonte.forEach((idxs, chave)=>{
    if(idxs.length < 2) return;
    const toks = idxs.map(i => _tokens(QUOTES[i].text));
    /* componentes conexas por similaridade */
    const pai = idxs.map((_, i) => i);
    const raiz = x => { while(pai[x] !== x) x = pai[x] = pai[pai[x]]; return x; };
    for(let i = 0; i < idxs.length; i++)
      for(let j = i + 1; j < idxs.length; j++)
        if(_similar(toks[i], toks[j]) >= 0.55){ const ri = raiz(i), rj = raiz(j); if(ri !== rj) pai[rj] = ri; }

    const clusters = new Map();
    idxs.forEach((_, i)=>{ const r = raiz(i); if(!clusters.has(r)) clusters.set(r, []); clusters.get(r).push(idxs[i]); });

    clusters.forEach(grupo=>{
      if(grupo.length < 2) return;
      const melhor = grupo.slice().sort((a,b)=>{
        const pa = QUOTES[a].st === 'A' ? 0 : 1, pb = QUOTES[b].st === 'A' ? 0 : 1;
        if(pa !== pb) return pa - pb;
        return QUOTES[b].text.length - QUOTES[a].text.length;
      })[0];
      VARIANTES.grupos++;
      grupo.forEach(i=>{
        QUOTES[i].vg = chave;
        QUOTES[i].vn = grupo.length;
        if(i !== melhor){ QUOTES[i].vdup = true; VARIANTES.ocultas++; }
      });
    });
  });
})();

/* Preferências de navegação. Ambas ligadas por padrão: a grade fica
   limpa e mostra só frases que o usuário pode conferir. */
state.exploreFilter.agrupar = true;      // uma frase por passagem
state.exploreFilter.somenteFonte = false; // exibir só A / A- / B

function getFilteredQuotes(){
  const { cat, q, profile, tradition, agrupar, somenteFonte } = state.exploreFilter;
  const query = normalizeSearch(q);
  const queryWords = query.split(/\s+/).filter(Boolean);
  const useProfile = cat === 'all' && profile && profile !== 'all';
  const useTrad = cat === 'fe' && tradition && tradition !== 'all';
  return QUOTES.map((quote,idx)=>({quote,idx})).filter(({quote})=>{
    if(!quoteMatchesCat(quote, cat)) return false;
    if(useProfile && !authorProfiles(quote.author).includes(profile)) return false;
    if(useTrad && authorTradition(quote.author) !== tradition) return false;
    /* variantes só somem quando o usuário está navegando; numa busca,
       o banco inteiro volta a ficar visível */
    if(agrupar && quote.vdup && !query) return false;
    if(somenteFonte && !['A','A-','B'].includes(quote.st)) return false;
    if(!query) return true;
    const haystack = normalizeSearch(quote.author + ' ' + quote.text);
    return haystack.includes(query) || queryWords.every(w => haystack.includes(w));
  });
}

/* ---- opções de curadoria dentro do painel de atuação ---- */
function renderCuradoriaOpcoes(){
  const box = document.getElementById('curadoriaOpcoes');
  if(!box) return;
  const f = state.exploreFilter;
  box.innerHTML = `
    <button class="cur-opt ${f.agrupar?'on':''}" data-cur="agrupar">
      <span class="cur-check">${f.agrupar?'✓':''}</span>
      <span>
        <strong>Uma frase por passagem</strong>
        <small>Oculta ${VARIANTES.ocultas} traduções repetidas da mesma origem. A busca continua encontrando todas.</small>
      </span>
    </button>
    <button class="cur-opt ${f.somenteFonte?'on':''}" data-cur="somenteFonte">
      <span class="cur-check">${f.somenteFonte?'✓':''}</span>
      <span>
        <strong>Somente frases com fonte</strong>
        <small>Mostra apenas o que tem obra documentada.</small>
      </span>
    </button>`;
  box.querySelectorAll('[data-cur]').forEach(b=>{
    b.addEventListener('click', ()=>{
      const k = b.dataset.cur;
      state.exploreFilter[k] = !state.exploreFilter[k];
      renderCuradoriaOpcoes();
      renderProfileFilter();
      renderExploreResults();
    });
  });
}

/* o painel de atuação passa a abrigar também as opções de curadoria */
function renderProfileFilter(){
  const wrap = document.getElementById('profileFilterWrap');
  if(!wrap) return;
  const isAll = state.exploreFilter.cat === 'all';
  wrap.classList.toggle('hidden', !isAll);
  if(!isAll){
    if(state.exploreFilter.profile !== 'all'){ state.exploreFilter.profile = 'all'; }
    closeProfilePanel();
    return;
  }
  const btn = document.getElementById('profileFilterBtn');
  const sel = state.exploreFilter.profile;
  const cur = sel==='all' ? null : profileById(sel);
  const extras = (state.exploreFilter.somenteFonte ? 1 : 0);
  btn.classList.toggle('has-value', !!cur || extras > 0);
  btn.querySelector('.pf-label').textContent = cur ? cur.name : 'Filtros';
  const opts = document.getElementById('profileOptions');
  opts.innerHTML = [{id:'all',name:'Todas as atuações',color:'var(--text-faint)'}, ...ACTIVE_PROFILES].map(p=>`
    <button class="profile-opt ${sel===p.id?'active':''}" data-profile="${p.id}">
      <span class="pd" style="background:${p.color}"></span>
      <span>${escapeHtml(p.name)}</span>
      <span class="pc">${p.id==='all' ? QUOTES.length : (PROFILE_COUNTS[p.id]||0)}</span>
    </button>`).join('');
  opts.querySelectorAll('[data-profile]').forEach(b=>{
    b.addEventListener('click', ()=>{
      state.exploreFilter.profile = b.dataset.profile;
      closeProfilePanel();
      renderProfileFilter();
      renderExploreResults();
    });
  });
  renderCuradoriaOpcoes();
}

/* ---- a expansão informa quantas versões da passagem existem ---- */
function procedenciaHTML(q){
  const rot = STATUS_ROTULO[q.st] || STATUS_ROTULO.R;
  let out = '';
  if(q.src) out += `<span class="expand-src">${escapeHtml(q.src)}</span>`;
  if(rot.texto) out += `<span class="expand-src ${rot.classe}">${escapeHtml(rot.texto)}</span>`;
  if(q.autorAnterior) out += `<span class="expand-src src-alerta">Circula como frase de ${escapeHtml(q.autorAnterior)}.</span>`;
  if(q.vn > 1) out += `<span class="expand-src src-nota">${q.vn} traduções desta mesma passagem no acervo.</span>`;
  return out;
}

function initFase3(){
  const tBtn = document.getElementById('traditionFilterBtn');
  if(tBtn) tBtn.addEventListener('click', (e)=>{ e.stopPropagation(); toggleTraditionPanel(); });
  document.addEventListener('click', (e)=>{
    const wrap = document.getElementById('traditionFilterWrap');
    if(wrap && !wrap.contains(e.target)) closeTraditionPanel();
  });
  const tClear = document.getElementById('traditionClear');
  if(tClear) tClear.addEventListener('click', ()=>{
    state.exploreFilter.tradition = 'all';
    closeTraditionPanel(); renderTraditionFilter(); renderExploreResults();
  });
  document.addEventListener('keydown', (e)=>{ if(e.key==='Escape') closeTraditionPanel(); });
}

/* ================================================================
   INICIALIZAÇÃO
   ================================================================ */
async function init(){
  await initTheme();
  await loadSession();
  await loadCommunityPosts();

  renderHeaderAuthArea();
  renderHeroStack();
  renderQuoteOfDay();
  renderCategoryGrid('catGridHome');
  renderStoriesGrid('storiesPreview', pickHomeStories(4));
  renderCommunityPreview();

  document.getElementById('statQuotes').textContent = QUOTES.length + '+';
  document.getElementById('statCats').textContent = CATEGORIES.length;
  document.getElementById('statAuthors').textContent = new Set(QUOTES.map(q=>q.author)).size + '+';

  initFase2();
  initFase3();
  prefetchStoryPhotos();
  navigateTo('home');
  observeReveals();
}
