/* ================================================================
   ÍNDICE DE AUTORES
   Une três fontes já existentes no site — biografias, frases e
   perfis — e acrescenta obras e feitos.
   ================================================================ */
const OBRAS = {};
const OBRA_POR_ID = {};
(function montarObras(){
  /* 1. obras curadas */
  Object.entries(OBRAS_CURADAS).forEach(([autor, lista])=>{
    if(!lista || !lista.length) return;
    const c = canonAuthor(autor.trim());
    OBRAS[c] = lista.map(([t,tipo,ano,d])=>({ t, tipo, ano, d, autor:c }));
  });
  /* 2. obras citadas nas próprias frases do acervo, quando ainda
        não estiverem na curadoria. Só entram fontes que nomeiam uma
        obra (com título), nunca "atribuído a" ou similares. */
  const conta = {};
  QUOTES.forEach(q=>{
    if(!q.src) return;
    const c = canonAuthor(q.author);
    if(SCRIPTURE_RE.test(c)) return;
    let titulo = String(q.src).split(/[,;(]/)[0].trim();
    titulo = titulo.replace(/\s+/g,' ').replace(/[.:]$/,'');
    if(titulo.length < 3 || titulo.length > 62) return;
    if(/^(atribu|citad|fonte|sem fonte|tradi|prov[eé]rbio|discurso de|entrevista|carta de)/i.test(titulo)) return;
    if(titulo.toLowerCase() === c.toLowerCase()) return;
    const k = c+'||'+titulo;
    conta[k] = (conta[k]||0)+1;
  });
  Object.entries(conta).forEach(([k,n])=>{
    const [c, titulo] = k.split('||');
    if(!OBRAS[c]) OBRAS[c] = [];
    const jaTem = OBRAS[c].some(o => o.t.toLowerCase().startsWith(titulo.toLowerCase().slice(0,14)));
    if(jaTem) return;
    if(n < 2) return;                       /* só entra se for fonte recorrente */
    OBRAS[c].push({
      t: titulo, tipo:'livro', ano:null, autor:c, citada:n,
      d:`Obra de ${c} citada no acervo do MeMotiva: ${n} passagens das frases publicadas aqui vêm desta fonte.`
    });
  });
  Object.keys(OBRAS).forEach(c=>{
    OBRAS[c].sort((a,b)=>(a.citada?1:0)-(b.citada?1:0));
    OBRAS[c].forEach((o,i)=>{ o.oid = slugify(c)+'--'+i; OBRA_POR_ID[o.oid] = o; });
  });
})();

function obrasDe(nome){ return OBRAS[canonAuthor(nome)] || []; }
function feitosDe(nome){ return FEITOS[canonAuthor(nome)] || []; }

/* papel/descrição curta da pessoa */
function papelDe(nome){
  const c = canonAuthor(nome);
  const s = STORIES.find(x=>canonAuthor(x.author)===c);
  if(s && s.role) return s.role;
  if(PAPEIS[c]) return PAPEIS[c];
  const perfis = authorProfiles(c).map(p=>profileById(p)).filter(Boolean);
  if(perfis.length) return perfis.map(p=>p.name).join(' · ');
  if(SCRIPTURE_RE.test(c)) return 'Texto e tradição do acervo';
  return 'Autor do acervo MeMotiva';
}
/* nascimento e morte, quando o papel traz as datas entre parênteses */
function datasDe(nome){
  const papel = papelDe(nome);
  const m = papel.match(/\(([^)]*)\)\s*$/);
  if(!m) return { nasc:null, morte:null, limpo:papel };
  const dentro = m[1].trim();
  const limpo = papel.replace(/\s*\([^)]*\)\s*$/,'').trim();
  const p = dentro.split(/[–—-]/).map(s=>s.trim());
  if(p.length === 2) return { nasc:p[0]||null, morte:p[1]||null, limpo };
  return { nasc:dentro, morte:null, limpo };
}

/* índice de todas as pessoas pesquisáveis */
const AUTOR_INDEX = (()=>{
  const m = new Map();
  const add = (nome)=>{
    const c = canonAuthor(nome);
    if(!c || SCRIPTURE_RE.test(c)) return;
    if(!m.has(c)) m.set(c, { nome:c, frases:[], story:null });
  };
  STORIES.forEach(s=>{ add(s.author); const c = canonAuthor(s.author); if(m.has(c)) m.get(c).story = s; });
  QUOTES.forEach((q,i)=>{ add(q.author); const c = canonAuthor(q.author); if(m.has(c)) m.get(c).frases.push(i); });
  Object.keys(OBRAS).forEach(add);
  return m;
})();
function autorInfo(nome){
  const c = canonAuthor(nome);
  const base = AUTOR_INDEX.get(c) || { nome:c, frases:[], story:null };
  const d = datasDe(c);
  return {
    nome: c,
    papel: papelDe(c),
    papelLimpo: d.limpo,
    nasc: d.nasc, morte: d.morte,
    story: base.story,
    frases: base.frases,
    obras: obrasDe(c),
    feitos: feitosDe(c),
    perfis: authorProfiles(c).map(p=>profileById(p)).filter(Boolean),
  };
}

/* ---------------- busca ---------------- */
function normTexto(s){
  return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
}
/* palavras que descrevem um campo de atuação, e não uma pessoa */
const CAMPO_ALIAS = {
  filosofos:['filosofia','filosofo','filosofos','filosofa','pensamento','pensadores','etica','estoicismo','sabedoria'],
  literatura:['literatura','escritor','escritores','escritora','poesia','poeta','poetas','romance','livros','literario','ficcao','contos'],
  cientistas:['ciencia','cientista','cientistas','fisica','quimica','biologia','matematica','astronomia','tecnologia','computacao','medicina'],
  educadores:['educacao','educador','educadores','pedagogia','ensino','professor','professores','escola','aprendizagem'],
  empresarios:['negocios','empresario','empresarios','empreendedorismo','empresa','startup','varejo','gestao de empresas'],
  investidores:['investimento','investimentos','investidor','investidores','financas','bolsa','acoes','dinheiro','mercado financeiro'],
  economistas:['economia','economista','economistas','macroeconomia','politica economica'],
  estrategistas:['estrategia','gestao','administracao','marketing','lideranca corporativa','produtividade','persuasao','negociacao','vendas'],
  politicos:['politica','politico','politicos','governo','estado','democracia','presidente','direito'],
  lideres:['lideranca','lider','lideres','comando','exercito','aviacao','exploracao'],
  ativistas:['ativismo','ativista','ativistas','direitos humanos','feminismo','direitos civis','luta','movimento'],
  religiosos:['religiao','religiosos','espiritualidade','fe','biblia','budismo','cristianismo','islamismo','hinduismo','misticismo','teologia'],
  psicologos:['psicologia','psicologo','psicologos','psicanalise','terapia','saude mental','emocoes','comportamento'],
  artistas:['arte','artista','artistas','pintura','musica','cinema','escultura','design','moda','fotografia'],
  atletas:['esporte','esportes','atleta','atletas','futebol','automobilismo','boxe','tenis','basquete','olimpiadas'],
  ditadores:['ditadura','ditador','ditadores','autoritarismo'],
};
function camposDaBusca(q){
  const n = normTexto(q);
  if(!n) return [];
  const out = [];
  Object.entries(CAMPO_ALIAS).forEach(([id, palavras])=>{
    const p = profileById(id);
    if(p && normTexto(p.name).includes(n)) { out.push(id); return; }
    if(palavras.some(w => w.startsWith(n) || n.startsWith(w) || w.includes(n))) out.push(id);
  });
  return [...new Set(out)];
}
function categoriasDaBusca(q){
  const n = normTexto(q);
  if(n.length < 3) return [];
  return CATEGORIES.filter(c => normTexto(c.name).includes(n)).map(c=>c.id);
}

function buscarAutores(q, limite=60){
  const n = normTexto(q);
  const campos = camposDaBusca(q);
  const cats = categoriasDaBusca(q);
  const res = [];
  AUTOR_INDEX.forEach((v, c)=>{
    let score = 0;
    const nn = normTexto(c);
    if(n){
      if(nn === n) score += 120;
      else if(nn.startsWith(n)) score += 90;
      else if(nn.includes(n)) score += 60;
    }
    const perfis = authorProfiles(c);
    if(campos.length && perfis.some(p=>campos.includes(p))) score += 45;
    if(cats.length && v.frases.some(i => quoteMatchesCat(QUOTES[i], cats[0]))) score += 26;
    if(n && !score){
      if(normTexto(papelDe(c)).includes(n)) score += 24;
      if(obrasDe(c).some(o=>normTexto(o.t).includes(n))) score += 34;
    }
    if(!n && !campos.length) score += 1;
    if(score <= 0) return;
    /* pessoas com biografia e com obras aparecem primeiro */
    if(v.story) score += 14;
    if(obrasDe(c).length) score += 8;
    score += Math.min(12, v.frases.length / 6);
    res.push({ nome:c, score });
  });
  res.sort((a,b)=> b.score - a.score || a.nome.localeCompare(b.nome,'pt'));
  return res.slice(0, limite).map(r=>r.nome);
}

function buscarObras(q, limite=80){
  const n = normTexto(q);
  const campos = camposDaBusca(q);
  const cats = categoriasDaBusca(q);
  const res = [];
  Object.entries(OBRAS).forEach(([autor, lista])=>{
    const perfis = authorProfiles(autor);
    const doCampo = campos.length && perfis.some(p=>campos.includes(p));
    lista.forEach(o=>{
      let score = 0;
      if(n){
        const tn = normTexto(o.t);
        if(tn === n) score += 120;
        else if(tn.startsWith(n)) score += 85;
        else if(tn.includes(n)) score += 62;
        if(normTexto(autor).includes(n)) score += 48;
        if(!score && normTexto(o.d).includes(n)) score += 14;
      }
      if(doCampo) score += 40;
      if(cats.length) score += 6;
      if(!n && !campos.length) score += 1;
      if(score <= 0) return;
      if(!o.citada) score += 12;          /* curadoria antes de fonte automática */
      if(o.tipo === 'feito') score -= 4;
      res.push({ o, score });
    });
  });
  res.sort((a,b)=> b.score - a.score || a.o.t.localeCompare(b.o.t,'pt'));
  /* evita que a tela vire uma lista de um autor só */
  const porAutor = {}; const fora = [];
  res.forEach(r=>{
    const k = r.o.autor;
    porAutor[k] = (porAutor[k]||0)+1;
    if(porAutor[k] <= 3) fora.push(r.o);
  });
  return fora.slice(0, limite);
}

/* ================================================================
   INJEÇÃO DAS NOVAS TELAS E DOS NOVOS ITENS DE NAVEGAÇÃO
   ================================================================ */
function f5InjectViews(){
  const main = document.getElementById('mainApp');
  if(!main) return;
  /* os destinos que já existiam foram ligados no carregamento do site */
  document.querySelectorAll('[data-nav]').forEach(el=>{ el.dataset.f5wired = '1'; });

  const html = `
  <!-- ---------- AUTORES & OBRAS ---------- -->
  <section class="view hidden" id="view-autores" data-view="autores">
    <div class="wrap section">
      <div class="section-head">
        <span class="eyebrow">acervo</span>
        <h2 class="section-title">Autores &amp; Obras</h2>
        <p class="section-sub">Procure uma pessoa, um campo de atuação ou uma obra — e aprofunde a partir daí.</p>
      </div>
      <div id="aoRoot"></div>
    </div>
  </section>

  <!-- ---------- PANORAMA DO AUTOR ---------- -->
  <section class="view hidden" id="view-panorama" data-view="panorama">
    <div class="wrap section">
      <div id="panRoot"></div>
    </div>
  </section>

  <!-- ---------- OBRA ---------- -->
  <section class="view hidden" id="view-obra" data-view="obra">
    <div class="wrap section">
      <div id="obraRoot"></div>
    </div>
  </section>

  <!-- ---------- ESCREVER ---------- -->
  <section class="view hidden" id="view-escrever" data-view="escrever">
    <div class="wrap section">
      <div class="section-head">
        <span class="eyebrow">seu espaço</span>
        <h2 class="section-title">Escrever</h2>
        <p class="section-sub">Escreva um relato, escolha o fundo, a mídia e a música — depois guarde só para você ou publique na comunidade.</p>
      </div>
      <div id="escRoot"></div>
    </div>
  </section>`;
  main.insertAdjacentHTML('beforeend', html);

  /* --- itens de navegação --- */
  const mainNav = document.querySelector('.main-nav');
  if(mainNav){
    const com = mainNav.querySelector('[data-nav="comunidade"]');
    const a = document.createElement('button'); a.className='nav-link'; a.dataset.nav='autores'; a.textContent='Autores & Obras';
    const e = document.createElement('button'); e.className='nav-link'; e.dataset.nav='escrever'; e.textContent='Escrever';
    mainNav.insertBefore(a, mainNav.querySelector('[data-nav="descubra"]') || com);
    mainNav.insertBefore(e, com);
  }
  const mob = document.querySelector('#mobileMenu nav');
  if(mob){
    const com = mob.querySelector('[data-nav="comunidade"]');
    const a = document.createElement('button'); a.className='nav-link'; a.dataset.nav='autores'; a.textContent='Autores & Obras';
    const e = document.createElement('button'); e.className='nav-link'; e.dataset.nav='escrever'; e.textContent='Escrever';
    mob.insertBefore(a, mob.querySelector('[data-nav="descubra"]') || com);
    mob.insertBefore(e, com);
  }
  const bn = document.querySelector('.bottom-nav');
  if(bn){
    const mk = (nav, label, ico)=>{
      const b = document.createElement('button');
      b.className='bn-item'; b.dataset.nav=nav;
      b.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${F5_ICONS[ico]}</svg>${label}`;
      return b;
    };
    bn.insertBefore(mk('autores','Autores','livro'), bn.querySelector('[data-nav="descubra"]'));
    bn.insertBefore(mk('escrever','Escrever','lapis'), bn.querySelector('[data-nav="perfil"]'));
    if(!bn.querySelector('[data-nav="comunidade"]')){
      bn.insertBefore(mk('comunidade','Comunidade','pessoas'), bn.querySelector('[data-nav="perfil"]'));
    }
  }

  /* liga os novos botões (os antigos já foram ligados no carregamento) */
  document.querySelectorAll('[data-nav]:not([data-f5wired])').forEach(el=>{
    el.dataset.f5wired = '1';
    el.addEventListener('click', ()=>navigateTo(el.dataset.nav));
  });
}

/* ================================================================
   AUTORES & OBRAS — fluxo de pesquisa
   ================================================================ */
const aoState = { modo:null, q:'', vis:'autores' };

function aoCardAutor(nome){
  const i = autorInfo(nome);
  const temObras = i.obras.length > 0;
  return `
  <article class="ao-card">
    <div class="ao-card-top">
      <div class="ao-thumb">
        ${photoImgHTML(i.nome,'card',180)}
        <div class="avatar-fallback" style="display:none; background:${colorForName(i.nome)};">${initials(i.nome)}</div>
      </div>
      <div style="min-width:0;">
        <h3 class="ao-name">${escapeHtml(i.nome)}</h3>
        <p class="ao-role">${escapeHtml(i.papel)}</p>
        ${temObras ? '' : '<p class="ao-none" style="margin-top:6px;">Obras: nenhum resultado relevante</p>'}
      </div>
    </div>
    <div class="ao-actions">
      <button class="ao-btn primary" data-pan="${escapeHtml(i.nome)}">Conhecer autor</button>
      ${temObras ? `<button class="ao-btn" data-verobras="${escapeHtml(i.nome)}">Ver obras</button>` : ''}
    </div>
  </article>`;
}
function aoCardObra(o){
  const t = tipoObra(o.tipo);
  return `
  <article class="obra-card">
    <div class="obra-head">
      <div class="obra-ico" style="background:${t.cor};">${f5svg(t.ico,20)}</div>
      <div style="min-width:0;">
        <h3 class="obra-title">${escapeHtml(o.t)}</h3>
        <p class="obra-author">${escapeHtml(o.autor)}${o.ano ? ' · '+escapeHtml(String(o.ano)) : ''}</p>
      </div>
    </div>
    <p class="obra-desc">${escapeHtml(o.d)}</p>
    <div class="ao-actions">
      <button class="ao-btn primary" data-obra="${o.oid}">Conhecer obra</button>
      <button class="ao-btn" data-comprar="${o.oid}">${f5svg('carrinho',15)} Comprar</button>
    </div>
  </article>`;
}

function renderAutoresObras(){
  const root = document.getElementById('aoRoot');
  if(!root) return;

  if(!aoState.modo){
    root.innerHTML = `
    <div class="ao-ask">
      <h3>Você deseja pesquisar por:</h3>
      <p>Escolha o ponto de partida. A tela muda conforme a sua escolha.</p>
      <div class="ao-choice">
        <button class="ao-big" data-modo="autor">
          ${f5svg('pessoa',26)}
          <b>Autor</b>
          <small>Procurar uma pessoa pelo nome</small>
        </button>
        <button class="ao-big" data-modo="obras">
          ${f5svg('livro',26)}
          <b>Obras / Campo</b>
          <small>Procurar por área ou por obra</small>
        </button>
      </div>
    </div>`;
    root.querySelectorAll('[data-modo]').forEach(b=>b.addEventListener('click', ()=>{
      aoState.modo = b.dataset.modo; aoState.q=''; aoState.vis='autores';
      renderAutoresObras();
      setTimeout(()=>{ const i = document.getElementById('aoInput'); if(i) i.focus(); }, 60);
    }));
    return;
  }

  const ehAutor = aoState.modo === 'autor';
  root.innerHTML = `
    <div class="ao-bar">
      <button class="ao-back" id="aoBack">${f5svg('voltar',15)} Voltar</button>
      <span class="ao-hint" style="margin:0;">${ehAutor ? 'Pesquisando por autor' : 'Pesquisando por obras ou campo'}</span>
    </div>
    <span class="f5-label">${ehAutor ? 'Pesquisar autor' : 'Pesquisar obras ou campo'}</span>
    <div class="f5-search">
      ${f5svg('busca',19)}
      <input type="text" id="aoInput" autocomplete="off" value="${escapeHtml(aoState.q)}"
        placeholder="${ehAutor ? 'Exemplo: Fernando Pessoa' : 'Exemplo: Literatura'}">
    </div>
    ${ehAutor ? '' : `
    <div class="ao-mode" style="margin-bottom:16px;">
      <button class="ao-tab ${aoState.vis==='autores'?'on':''}" data-vis="autores">Apenas autores</button>
      <button class="ao-tab ${aoState.vis==='obras'?'on':''}" data-vis="obras">Apenas obras</button>
    </div>`}
    <div id="aoResults"></div>`;

  document.getElementById('aoBack').addEventListener('click', ()=>{ aoState.modo=null; renderAutoresObras(); });
  const input = document.getElementById('aoInput');
  let tm=null;
  input.addEventListener('input', ()=>{
    aoState.q = input.value;
    clearTimeout(tm); tm = setTimeout(aoRenderResultados, 170);
  });
  root.querySelectorAll('[data-vis]').forEach(b=>b.addEventListener('click', ()=>{
    aoState.vis = b.dataset.vis; renderAutoresObras();
    setTimeout(()=>{ const i=document.getElementById('aoInput'); if(i){ i.focus(); i.setSelectionRange(i.value.length,i.value.length);} },50);
  }));
  aoRenderResultados();
}

function aoRenderResultados(){
  const box = document.getElementById('aoResults');
  if(!box) return;
  const q = aoState.q.trim();
  const ehAutor = aoState.modo === 'autor';
  const mostrarObras = !ehAutor && aoState.vis === 'obras';

  if(!q){
    box.innerHTML = ehAutor
      ? `<p class="ao-hint">Digite o nome de quem você quer conhecer. Exemplo: <b>Fernando Pessoa</b>.</p>${aoSugestoes()}`
      : `<p class="ao-hint">Digite um campo (<b>Literatura</b>, <b>Filosofia</b>, <b>Ciência</b>, <b>Negócios</b>…) ou o nome de uma obra.</p>${aoSugestoesCampo()}`;
    aoWire(box);
    return;
  }

  if(mostrarObras){
    const lista = buscarObras(q);
    box.innerHTML = lista.length
      ? `<p class="f5-count">${lista.length === 1 ? '1 obra encontrada' : lista.length+' obras encontradas'}</p>
         <div class="ao-list">${lista.map(aoCardObra).join('')}</div>`
      : `<div class="empty-state"><h3>Nenhuma obra com esse termo</h3><p>Tente outro campo ou procure pelo nome do autor.</p></div>`;
  }else{
    const lista = buscarAutores(q);
    box.innerHTML = lista.length
      ? `<p class="f5-count">${lista.length === 1 ? '1 pessoa encontrada' : lista.length+' pessoas encontradas'}</p>
         <div class="ao-list">${lista.map(aoCardAutor).join('')}</div>`
      : `<div class="empty-state"><h3>Nenhuma pessoa com esse termo</h3><p>Tente outro nome ou procure por um campo de atuação.</p></div>`;
  }
  aoWire(box);
}
function aoSugestoes(){
  const nomes = ['Fernando Pessoa','Machado de Assis','Clarice Lispector','Marco Aurélio','Marie Curie','Nelson Mandela'];
  return `<div class="ao-list">${nomes.filter(n=>AUTOR_INDEX.has(canonAuthor(n))).map(aoCardAutor).join('')}</div>`;
}
function aoSugestoesCampo(){
  const campos = ['Literatura','Filosofia','Ciência','Negócios','Psicologia','Arte','Esporte','Religião'];
  return `<div class="ao-mode" style="flex-wrap:wrap;">${campos.map(c=>`<button class="ao-tab" data-campo="${c}">${c}</button>`).join('')}</div>`;
}
function aoWire(scope){
  scope.querySelectorAll('[data-campo]').forEach(b=>b.addEventListener('click', ()=>{
    aoState.q = b.dataset.campo;
    const i = document.getElementById('aoInput'); if(i) i.value = aoState.q;
    aoRenderResultados();
  }));
  scope.querySelectorAll('[data-pan]').forEach(b=>b.addEventListener('click', ()=>abrirPanorama(b.dataset.pan)));
  scope.querySelectorAll('[data-verobras]').forEach(b=>b.addEventListener('click', ()=>abrirPanorama(b.dataset.verobras, 'obras')));
  scope.querySelectorAll('[data-obra]').forEach(b=>b.addEventListener('click', ()=>abrirObra(b.dataset.obra)));
  scope.querySelectorAll('[data-comprar]').forEach(b=>b.addEventListener('click', (e)=>{
    e.stopPropagation();
    const o = OBRA_POR_ID[b.dataset.comprar];
    if(o) acionarComprar(o.autor, o.t);
  }));
  /* fotos com fallback */
  scope.querySelectorAll('.ao-thumb img').forEach(img=>{ img.loading='lazy'; });
}

/* ----------------------------------------------------------------
   BOTÃO "COMPRAR"
   Nesta etapa é só elemento visual e estrutural. Nenhuma loja,
   nenhum link de afiliado, nenhum rastreamento. O ponto de entrada
   abaixo existe justamente para receber a função depois, sem que
   nada da interface precise ser refeito.
   ---------------------------------------------------------------- */
window.MEMOTIVA_COMPRAR = window.MEMOTIVA_COMPRAR || null;
function acionarComprar(autor, titulo){
  if(typeof window.MEMOTIVA_COMPRAR === 'function'){
    try{ window.MEMOTIVA_COMPRAR({ autor, titulo }); return; }catch(e){ /* segue para o aviso */ }
  }
  toast('A função do botão Comprar ainda será definida em uma próxima etapa.', 3200);
}

/* ================================================================
   PANORAMA DO AUTOR
   ================================================================ */
let panAtual = null;
function abrirPanorama(nome, ancora){
  panAtual = canonAuthor(nome);
  navigateTo('panorama');
  if(ancora){
    setTimeout(()=>{
      const el = document.getElementById('pan-'+ancora);
      if(el) el.scrollIntoView({ behavior: prefersReducedMotion()?'auto':'smooth', block:'start' });
    }, 260);
  }
}
function renderPanorama(){
  const root = document.getElementById('panRoot');
  if(!root) return;
  if(!panAtual){
    root.innerHTML = `<div class="empty-state"><h3>Escolha uma pessoa</h3><p>Use Autores &amp; Obras para procurar alguém.</p></div>`;
    return;
  }
  const i = autorInfo(panAtual);
  const s = i.story;
  const idAudio = 'pan_'+slugify(i.nome);
  const textoAudio = s ? `${i.nome}. ${s.title}. ${s.text}` : null;

  const frasesHTML = i.frases.length
    ? `<div class="quote-grid">${i.frases.slice(0,12).map(idx=>quoteCardHTML(QUOTES[idx], idx)).join('')}</div>
       ${i.frases.length>12 ? `<p class="ao-hint" style="margin-top:12px;">e mais ${i.frases.length-12} frases no acervo — veja todas em Explorar.</p>` : ''}`
    : `<p class="pan-empty">Ainda não há frases desta pessoa no acervo.</p>`;

  const obrasHTML = i.obras.length
    ? `<div class="ao-list">${i.obras.map(aoCardObra).join('')}</div>`
    : `<p class="pan-empty">Obras: nenhum resultado relevante. Esta pessoa é lembrada sobretudo pelo que fez.</p>`;

  root.innerHTML = `
    <div class="ao-bar">
      <button class="ao-back" id="panBack">${f5svg('voltar',15)} Voltar</button>
    </div>

    <div class="pan-hero">
      <div class="pan-photo" id="panPhoto" role="button" tabindex="0" aria-label="Ampliar fotografia">
        ${photoImgHTML(i.nome,'card',520)}
        <div class="avatar-fallback" style="display:none; background:${colorForName(i.nome)};">${initials(i.nome)}</div>
      </div>
      <div class="pan-id">
        <h2 class="pan-name">${escapeHtml(i.nome)}</h2>
        <p class="pan-role">${escapeHtml(i.papelLimpo)}</p>
        ${(i.nasc || i.morte) ? `<div class="pan-dates">
          ${i.nasc ? `<div class="pan-date"><b>Nascimento</b><span>${escapeHtml(i.nasc)}</span></div>` : ''}
          ${i.morte ? `<div class="pan-date"><b>Morte</b><span>${escapeHtml(i.morte)}</span></div>` : ''}
          ${i.frases.length ? `<div class="pan-date"><b>Frases no acervo</b><span>${i.frases.length}</span></div>` : ''}
          ${i.obras.length ? `<div class="pan-date"><b>Obras</b><span>${i.obras.length}</span></div>` : ''}
        </div>` : ''}
        ${i.perfis.length ? `<div class="pan-tags">${i.perfis.map(p=>`<span class="discover-tag">${escapeHtml(p.name)}</span>`).join('')}</div>` : ''}
      </div>
    </div>

    <div class="pan-jump">
      ${s ? `<button data-jump="bio">Trajetória e biografia</button>` : ''}
      ${i.feitos.length ? `<button data-jump="feitos">Feitos</button>` : ''}
      <button data-jump="frases">Ver frases</button>
      <button data-jump="obras">Ver obras</button>
    </div>

    ${s ? `
    <section class="pan-sec" id="pan-bio">
      <h3>Trajetória e biografia</h3>
      <div class="pan-audio">
        <button class="play-btn" data-story-play="${idAudio}" aria-label="Reproduzir narração">${playIconSVG()}</button>
        <select class="voice-select" data-voice-for="${idAudio}">
          <option value="female">Voz feminina</option>
          <option value="male">Voz masculina</option>
        </select>
        <span class="audio-status" data-status-for="${idAudio}">Toque para ouvir</span>
      </div>
      <div class="pan-bio">
        <p><b>${escapeHtml(s.title)}</b> — ${escapeHtml(s.excerpt)}</p>
        <p>${escapeHtml(s.text).replace(/\n\n/g,'</p><p>')}</p>
      </div>
    </section>` : `
    <section class="pan-sec" id="pan-bio">
      <h3>Sobre</h3>
      <div class="pan-bio"><p>${escapeHtml(i.papel)}. ${i.frases.length ? `Está no acervo do MeMotiva com ${i.frases.length} ${i.frases.length===1?'frase':'frases'}.` : ''} ${i.obras.length ? `Tem ${i.obras.length} ${i.obras.length===1?'obra catalogada':'obras catalogadas'} aqui.` : ''}</p></div>
    </section>`}

    ${i.feitos.length ? `
    <section class="pan-sec" id="pan-feitos">
      <h3>Feitos e contribuições</h3>
      <ul class="pan-feitos">${i.feitos.map(f=>`<li>${escapeHtml(f)}</li>`).join('')}</ul>
    </section>` : ''}

    <section class="pan-sec" id="pan-frases">
      <h3>Frases</h3>
      ${frasesHTML}
    </section>

    <section class="pan-sec" id="pan-obras">
      <h3>Obras</h3>
      ${obrasHTML}
    </section>`;

  document.getElementById('panBack').addEventListener('click', ()=>{
    navigateTo(panVoltarPara || 'autores');
  });
  root.querySelectorAll('[data-jump]').forEach(b=>b.addEventListener('click', ()=>{
    const el = document.getElementById('pan-'+b.dataset.jump);
    if(el) el.scrollIntoView({ behavior: prefersReducedMotion()?'auto':'smooth', block:'start' });
  }));
  const foto = document.getElementById('panPhoto');
  if(foto){
    const go = ()=>openPhotoModal(i.nome);
    foto.addEventListener('click', go);
    foto.addEventListener('keydown', e=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); go(); } });
  }
  /* narração — mesma lógica das biografias */
  const btn = root.querySelector('[data-story-play]');
  if(btn && textoAudio){
    btn.addEventListener('click', ()=>{
      const st = root.querySelector('[data-status-for]');
      const vs = root.querySelector('[data-voice-for]');
      toggleStoryAudio(idAudio, textoAudio, btn, st, vs);
    });
  }
  attachQuoteCardEvents(root);
  requestAnimationFrame(observeReveals);
}
let panVoltarPara = 'autores';

/* ================================================================
   TELA DA OBRA
   ================================================================ */
let obraAtual = null;
function abrirObra(oid){
  obraAtual = OBRA_POR_ID[oid] || null;
  if(!obraAtual){ toast('Obra não encontrada.'); return; }
  obraVoltarPara = state.view === 'obra' ? obraVoltarPara : state.view;
  navigateTo('obra');
}
let obraVoltarPara = 'autores';
function renderObra(){
  const root = document.getElementById('obraRoot');
  if(!root) return;
  if(!obraAtual){
    root.innerHTML = `<div class="empty-state"><h3>Escolha uma obra</h3><p>Use Autores &amp; Obras para procurar.</p></div>`;
    return;
  }
  const o = obraAtual;
  const t = tipoObra(o.tipo);
  const i = autorInfo(o.autor);
  const citacoes = i.frases.filter(idx=>{
    const q = QUOTES[idx];
    return q.src && normTexto(q.src).startsWith(normTexto(o.t).slice(0,12));
  }).slice(0,6);

  root.innerHTML = `
    <div class="ao-bar"><button class="ao-back" id="obraBack">${f5svg('voltar',15)} Voltar</button></div>
    <div class="pan-hero" style="align-items:center;">
      <div class="obra-ico" style="background:${t.cor}; width:74px; height:74px; border-radius:16px;">${f5svg(t.ico,34)}</div>
      <div class="pan-id">
        <span class="obra-meta">${escapeHtml(t.nome)}${o.ano ? ' · '+escapeHtml(String(o.ano)) : ''}</span>
        <h2 class="pan-name" style="margin-top:4px;">${escapeHtml(o.t)}</h2>
        <p class="pan-role">${escapeHtml(o.autor)} — ${escapeHtml(i.papelLimpo)}</p>
      </div>
    </div>

    <section class="pan-sec">
      <h3>O que é esta obra</h3>
      <div class="pan-bio"><p>${escapeHtml(o.d)}</p></div>
    </section>

    <section class="pan-sec">
      <h3>Por que ela importa</h3>
      <div class="pan-bio"><p>${escapeHtml(relevanciaObra(o, i))}</p></div>
    </section>

    ${citacoes.length ? `
    <section class="pan-sec">
      <h3>Passagens desta obra no acervo</h3>
      <div class="quote-grid">${citacoes.map(idx=>quoteCardHTML(QUOTES[idx], idx)).join('')}</div>
    </section>` : ''}

    <div class="ao-actions" style="max-width:520px;">
      <button class="ao-btn primary" id="obraAutor">Conhecer autor</button>
      <button class="ao-btn" id="obraComprar">${f5svg('carrinho',15)} Comprar</button>
    </div>`;

  document.getElementById('obraBack').addEventListener('click', ()=>navigateTo(obraVoltarPara || 'autores'));
  document.getElementById('obraAutor').addEventListener('click', ()=>abrirPanorama(o.autor));
  document.getElementById('obraComprar').addEventListener('click', ()=>acionarComprar(o.autor, o.t));
  attachQuoteCardEvents(root);
  requestAnimationFrame(observeReveals);
}
function relevanciaObra(o, i){
  const partes = [];
  const t = tipoObra(o.tipo).nome.toLowerCase();
  if(o.citada) partes.push(`É uma das fontes mais citadas do acervo do MeMotiva: ${o.citada} passagens publicadas aqui vêm dela.`);
  if(o.ano) partes.push(`Publicada em ${o.ano}, continua sendo uma das referências centrais para quem quer entender ${i.nome}.`);
  else partes.push(`Está entre as referências centrais para quem quer entender ${i.nome}.`);
  if(i.perfis.length) partes.push(`Costuma ser lida por quem se interessa por ${i.perfis.map(p=>p.name.toLowerCase()).join(', ')}.`);
  partes.push(`Categoria: ${t}.`);
  return partes.join(' ');
}

/* ================================================================
   MOTOR DE ÁUDIO DAS TRILHAS
   As trilhas são sintetizadas no próprio navegador (Web Audio API):
   tocam sem rede, sem serviço externo e sem ocupar armazenamento.
   A pessoa também pode anexar uma música do próprio aparelho.
   ================================================================ */
const Musica = {
  ctx:null, master:null, tocando:null, timer:null, audioEl:null, fim:null,

  ensure(){
    if(!this.ctx){
      const AC = window.AudioContext || window.webkitAudioContext;
      if(!AC) return null;
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.85;
      this.master.connect(this.ctx.destination);
    }
    if(this.ctx.state === 'suspended') this.ctx.resume();
    return this.ctx;
  },

  /* gerador determinístico: a mesma trilha soa sempre igual */
  _rng(seed){
    let s = 0;
    for(let i=0;i<seed.length;i++) s = (s*31 + seed.charCodeAt(i)) >>> 0;
    return ()=>{ s = (s*1664525 + 1013904223) >>> 0; return s / 4294967296; };
  },
  _escala(raiz, tipo){
    const maior = [0,2,4,5,7,9,11], menor = [0,2,3,5,7,8,10];
    const g = tipo === 'menor' ? menor : maior;
    const out = [];
    for(let oct=-1; oct<=2; oct++) g.forEach(n=>out.push(raiz + n + oct*12));
    return out.sort((a,b)=>a-b);
  },
  _hz(midi){ return 440 * Math.pow(2, (midi-69)/12); },

  /* lista de notas [{t, dur, midi, vol, papel}] para a trilha inteira */
  plano(tr){
    if(tr._plano) return tr._plano;
    const rnd = this._rng(tr.id + tr.nome);
    const esc = this._escala(tr.raiz, tr.esc);
    const bat = 60 / tr.bpm;
    const compasso = bat * 4;
    const notas = [];
    const graus = tr.esc === 'menor' ? [0,5,3,6] : [0,4,5,3];
    let t = 0, c = 0;
    while(t < tr.dur){
      const base = tr.raiz - 12 + graus[c % graus.length];
      /* acorde sustentado */
      [0,4,7].forEach((iv,k)=>{
        notas.push({ t, dur: compasso*0.98, midi: base + (tr.esc==='menor' && iv===4 ? 3 : iv), vol: k===0?0.18:0.11, papel:'acorde' });
      });
      /* baixo */
      notas.push({ t, dur: compasso*0.9, midi: base-12, vol:0.16, papel:'baixo' });
      /* melodia */
      const n = 3 + Math.floor(rnd()*3);
      for(let i=0;i<n;i++){
        const pos = t + (compasso/n)*i + rnd()*0.08;
        if(pos >= tr.dur) break;
        const alvo = esc.filter(x => x >= tr.raiz && x <= tr.raiz+14);
        const midi = alvo[Math.floor(rnd()*alvo.length)] || tr.raiz;
        notas.push({ t:pos, dur: (compasso/n)*(0.7+rnd()*0.6), midi, vol:0.14+rnd()*0.07, papel:'melodia' });
      }
      t += compasso; c++;
    }
    tr._plano = notas;
    return notas;
  },

  _timbre(papel, timbre){
    switch(timbre){
      case 'piano':  return { tipo: papel==='melodia'?'triangle':'sine',    corte: 2600, ata:0.008, dec:0.9 };
      case 'violao': return { tipo: papel==='melodia'?'sawtooth':'triangle',corte: 1900, ata:0.005, dec:0.7 };
      case 'cordas': return { tipo:'sawtooth',                              corte: 1500, ata:0.18,  dec:1.4 };
      case 'pad':    return { tipo:'sine',                                  corte: 1100, ata:0.35,  dec:1.8 };
      case 'lofi':   return { tipo: papel==='melodia'?'square':'triangle',  corte: 1300, ata:0.02,  dec:0.8 };
      default:       return { tipo:'triangle',                              corte: 2100, ata:0.05,  dec:1.1 };
    }
  },

  tocarTrilha(tr, de=0, ate=null, onFim){
    const ctx = this.ensure();
    if(!ctx) { toast('Este navegador não permite reproduzir a trilha.'); return false; }
    this.parar();
    ate = (ate == null) ? Math.min(tr.dur, de + 30) : ate;
    const dur = Math.max(1, ate - de);
    const t0 = ctx.currentTime + 0.06;
    const notas = this.plano(tr).filter(n => n.t >= de - 0.5 && n.t < ate);
    const vozes = [];
    notas.forEach(n=>{
      const cfg = this._timbre(n.papel, tr.timbre);
      const inicio = t0 + Math.max(0, n.t - de);
      const d = Math.min(n.dur, ate - Math.max(n.t, de)) ;
      if(d <= 0.02) return;
      const osc = ctx.createOscillator();
      const g = ctx.createGain();
      const f = ctx.createBiquadFilter();
      osc.type = cfg.tipo;
      osc.frequency.value = this._hz(n.midi);
      f.type = 'lowpass'; f.frequency.value = cfg.corte;
      g.gain.setValueAtTime(0.0001, inicio);
      g.gain.exponentialRampToValueAtTime(Math.max(0.002, n.vol), inicio + cfg.ata);
      g.gain.exponentialRampToValueAtTime(0.0001, inicio + d * (0.6 + cfg.dec*0.2) + 0.08);
      osc.connect(f); f.connect(g); g.connect(this.master);
      osc.start(inicio); osc.stop(inicio + d + 0.3);
      vozes.push(osc);
    });
    this.tocando = { tipo:'trilha', id:tr.id, vozes };
    this.fim = onFim || null;
    this.timer = setTimeout(()=>{ this.parar(); if(onFim) onFim(); }, dur*1000 + 250);
    return true;
  },

  tocarArquivo(src, de=0, ate=null, onFim){
    this.parar();
    const a = new Audio(src);
    a.currentTime = de || 0;
    a.play().catch(()=>toast('Não foi possível reproduzir este áudio.'));
    this.audioEl = a;
    this.tocando = { tipo:'arquivo', id:src };
    this.fim = onFim || null;
    const parar = ()=>{ this.parar(); if(onFim) onFim(); };
    if(ate){ this.timer = setTimeout(parar, Math.max(500,(ate-de)*1000)); }
    a.addEventListener('ended', parar, { once:true });
    return true;
  },

  tocarRef(mus, onFim){
    if(!mus) return false;
    if(mus.tipo === 'trilha'){
      const tr = TRILHAS.find(t=>t.id===mus.id);
      if(!tr) return false;
      return this.tocarTrilha(tr, mus.de||0, mus.ate||null, onFim);
    }
    if(mus.src) return this.tocarArquivo(mus.src, mus.de||0, mus.ate||null, onFim);
    toast('Este áudio só fica disponível na sessão em que foi anexado.');
    return false;
  },

  parar(){
    clearTimeout(this.timer); this.timer = null;
    if(this.tocando && this.tocando.vozes){
      this.tocando.vozes.forEach(o=>{ try{ o.stop(); }catch(e){} });
    }
    if(this.audioEl){ try{ this.audioEl.pause(); }catch(e){} this.audioEl = null; }
    this.tocando = null;
  },
  estaTocando(id){ return !!(this.tocando && this.tocando.id === id); },
};

/* ================================================================
   ESTADO DO COMPOSITOR "ESCREVER"
   ================================================================ */
const escState = {
  texto:'', fonte:'hand', cor:'paper',
  fundo:null,        /* {cat, i, nome, css, ink} */
  media:null,        /* {tipo:'imagem'|'video', src, filtro, legenda, persistir} */
  musica:null,       /* {tipo:'trilha'|'arquivo', id, nome, de, ate, src, persistir} */
  quote:null,        /* {text, author, idx} */
  painel:null,       /* 'galeria' | 'musica' | null */
  catFundo:'paisagens',
  buscaMus:'',
};

function fundoPorRef(ref){
  if(!ref) return null;
  const cat = FUNDOS.find(c=>c.id===ref.cat);
  if(!cat || !cat.itens[ref.i]) return null;
  const [nome, css, ink] = cat.itens[ref.i];
  return { cat:ref.cat, i:ref.i, nome, css, ink };
}
function escFundoCSS(){
  if(escState.fundo) return escState.fundo.css;
  const c = STYLE_COLORS.find(x=>x.id===escState.cor) || STYLE_COLORS[0];
  return (state.theme === 'dark' && c.dark) ? c.dark : c.bg;
}
function escTinta(){
  if(escState.fundo) return escState.fundo.ink;
  if(escState.cor === 'paper') return 'var(--paper-text)';
  return state.theme === 'dark' ? '#F3ECE3' : '#1B1817';
}

/* ================================================================
   TELA "ESCREVER"
   ================================================================ */
function renderEscrever(){
  const root = document.getElementById('escRoot');
  if(!root) return;
  const fonte = STYLE_FONTS.find(f=>f.id===escState.fonte) || STYLE_FONTS[0];
  const temMedia = !!escState.media;

  root.innerHTML = `
  <div class="esc-wrap">
    <div class="esc-card">
      <div class="composer-head" style="margin-bottom:12px;">
        ${state.currentUser
          ? `<div class="composer-avatar" style="background:${colorForName(state.currentUser.username)}; display:flex; align-items:center; justify-content:center; color:#fff; font-weight:800; font-size:13px;">${initials(state.currentUser.username)}</div><b>${escapeHtml(state.currentUser.username)}</b>`
          : `<span style="color:var(--text-faint); font-size:14px;">Entre para guardar ou publicar o que escrever</span>`}
      </div>

      <div class="esc-preview ${temMedia?'has-media':''}" id="escPreview"
           style="background:${escFundoCSS()}; color:${escTinta()};">
        ${temMedia ? `
          <div class="esc-media-layer">
            ${escState.media.tipo==='video'
              ? `<video src="${escState.media.src}" autoplay muted loop playsinline style="filter:${escState.media.filtro||'none'}"></video>`
              : `<img src="${escState.media.src}" alt="" style="filter:${escState.media.filtro||'none'}">`}
          </div>
          <div class="esc-media-scrim"></div>` : ''}
        <div class="esc-preview-inner" ${temMedia?'style="color:#fff; text-shadow:0 2px 12px rgba(0,0,0,.5);"':''}>
          ${escState.quote ? `
          <div class="esc-quote-ref">
            <button class="esc-qr-del" id="escQrDel" aria-label="Remover frase anexada">${f5svg('fechar',14)}</button>
            <p>&ldquo;${escapeHtml(escState.quote.text)}&rdquo;</p>
            <span>— ${escapeHtml(escState.quote.author)}</span>
          </div>` : ''}
          <textarea id="escTexto" maxlength="900" style="font-family:${fonte.family};"
            placeholder="${escState.quote ? 'Escreva o que essa frase te trouxe…' : 'O que você está vivendo hoje? Escreva um relato, uma frase, um lembrete…'}">${escapeHtml(escState.texto)}</textarea>
        </div>
      </div>

      <div class="esc-toolbar">
        <span class="esc-tool-label">Estilo do cartão</span>
        <div class="font-row" id="escFontes">
          ${STYLE_FONTS.map(f=>`<button class="font-opt ${escState.fonte===f.id?'active':''}" data-font="${f.id}" style="font-family:${f.family}">${f.label}</button>`).join('')}
        </div>
      </div>
      <div class="esc-toolbar">
        <div class="bg-row" id="escCores">
          ${STYLE_COLORS.map(c=>`<button class="bg-opt ${(!escState.fundo && escState.cor===c.id)?'active':''}" data-color="${c.id}" style="background:${c.bg}" aria-label="Estilo ${c.id}"></button>`).join('')}
        </div>
        <button class="esc-tool ${escState.painel==='galeria'?'on':''}" id="escGaleria" title="Galeria de fundos" aria-label="Galeria de fundos">${f5svg('galeria',20)}</button>
        <button class="esc-tool" id="escMais" title="Adicionar foto ou vídeo" aria-label="Adicionar foto ou vídeo">${f5svg('mais',20)}</button>
        <button class="esc-tool ${escState.painel==='musica'?'on':''}" id="escMusica" title="Adicionar música" aria-label="Adicionar música">${f5svg('nota',20)}</button>
        ${temMedia ? `<button class="esc-tool" id="escEditarMedia" title="Editar mídia" aria-label="Editar mídia">${f5svg('lapis',20)}</button>` : ''}
        ${temMedia ? `<button class="esc-tool" id="escRemoverMedia" title="Remover mídia" aria-label="Remover mídia">${f5svg('lixo',20)}</button>` : ''}
      </div>

      <div id="escPainel"></div>

      ${escState.musica ? `
      <div class="esc-panel" style="display:flex;align-items:center;gap:10px;">
        <span class="mus-play" id="escMusPrev">${f5svg('play',14,'currentColor',0)}</span>
        <div class="mus-meta">
          <b>${escapeHtml(escState.musica.nome)}</b>
          <small>trecho de ${fmtSeg(escState.musica.de)} a ${fmtSeg(escState.musica.ate)}${escState.musica.persistir===false?' · disponível nesta sessão':''}</small>
        </div>
        <button class="esc-tool" id="escMusDel" aria-label="Remover música">${f5svg('lixo',18)}</button>
      </div>` : ''}

      <div class="esc-actions">
        <button class="btn btn-coral btn-lg" id="escPublicar">Publicar na comunidade</button>
        <button class="btn btn-outline btn-lg" id="escGuardar">Guardar relato pessoal</button>
      </div>
      <p class="esc-note">Filtro de linguagem ativo · publicações passam por moderação. O relato pessoal é privado: só você vê.</p>
    </div>
  </div>
  <input type="file" id="escFile" accept="image/*,video/*" style="display:none">
  <input type="file" id="escAudioFile" accept="audio/*" style="display:none">`;

  wireEscrever();
}

function fmtSeg(s){
  s = Math.max(0, Math.round(s||0));
  const m = Math.floor(s/60), r = s%60;
  return m+':'+String(r).padStart(2,'0');
}

function wireEscrever(){
  const root = document.getElementById('escRoot');
  const ta = document.getElementById('escTexto');
  if(ta){
    ta.addEventListener('input', ()=>{ escState.texto = ta.value; });
    ta.style.height = 'auto';
  }
  root.querySelectorAll('#escFontes .font-opt').forEach(b=>b.addEventListener('click', ()=>{
    escState.fonte = b.dataset.font; renderEscrever();
  }));
  root.querySelectorAll('#escCores .bg-opt').forEach(b=>b.addEventListener('click', ()=>{
    escState.cor = b.dataset.color; escState.fundo = null; renderEscrever();
  }));

  const qrDel = document.getElementById('escQrDel');
  if(qrDel) qrDel.addEventListener('click', ()=>{ escState.quote = null; renderEscrever(); });

  document.getElementById('escGaleria').addEventListener('click', ()=>{
    escState.painel = escState.painel==='galeria' ? null : 'galeria'; renderEscrever();
  });
  document.getElementById('escMusica').addEventListener('click', ()=>{
    escState.painel = escState.painel==='musica' ? null : 'musica'; renderEscrever();
  });
  document.getElementById('escMais').addEventListener('click', ()=>{
    document.getElementById('escFile').click();
  });
  document.getElementById('escFile').addEventListener('change', (e)=>{
    const f = e.target.files && e.target.files[0];
    if(f) abrirEditorMidia(f);
    e.target.value = '';
  });
  const edt = document.getElementById('escEditarMedia');
  if(edt) edt.addEventListener('click', ()=>{ if(escState.media) abrirEditorMidia(null, escState.media); });
  const rem = document.getElementById('escRemoverMedia');
  if(rem) rem.addEventListener('click', ()=>{ escState.media = null; renderEscrever(); });

  const mp = document.getElementById('escMusPrev');
  if(mp) mp.addEventListener('click', ()=>{
    if(Musica.estaTocando(escState.musica.id)){ Musica.parar(); mp.innerHTML = f5svg('play',14,'currentColor',0); return; }
    mp.innerHTML = f5svg('pausa',14,'currentColor',0);
    Musica.tocarRef(escState.musica, ()=>{ mp.innerHTML = f5svg('play',14,'currentColor',0); });
  });
  const md = document.getElementById('escMusDel');
  if(md) md.addEventListener('click', ()=>{ Musica.parar(); escState.musica = null; renderEscrever(); });

  if(escState.painel === 'galeria') renderPainelGaleria();
  if(escState.painel === 'musica') renderPainelMusica();

  document.getElementById('escPublicar').addEventListener('click', ()=>{
    requireAuth(()=>enviarRelato('comunidade'), 'Crie sua conta para publicar na comunidade.');
  });
  document.getElementById('escGuardar').addEventListener('click', ()=>{
    requireAuth(()=>enviarRelato('pessoal'), 'Crie sua conta para guardar relatos pessoais.');
  });
}

/* ---------------- painel: galeria de fundos ---------------- */
function renderPainelGaleria(){
  const box = document.getElementById('escPainel');
  const cat = FUNDOS.find(c=>c.id===escState.catFundo) || FUNDOS[0];
  box.innerHTML = `
  <div class="esc-panel">
    <div class="esc-panel-head">
      <b>Galeria de fundos</b>
      <button class="ao-back" id="escFundoLimpar">Sem fundo</button>
    </div>
    <div class="esc-cats">
      ${FUNDOS.map(c=>`<button class="${c.id===cat.id?'on':''}" data-catfundo="${c.id}">${escapeHtml(c.nome)}</button>`).join('')}
    </div>
    <div class="esc-grid-bg">
      ${cat.itens.map(([nome,css],i)=>{
        const on = escState.fundo && escState.fundo.cat===cat.id && escState.fundo.i===i;
        return `<button class="esc-bg-opt ${on?'on':''}" data-fundo="${cat.id}|${i}" style="background:${css}; background-size:cover;" aria-label="${escapeHtml(nome)}"><span>${escapeHtml(nome)}</span></button>`;
      }).join('')}
    </div>
  </div>`;
  box.querySelectorAll('[data-catfundo]').forEach(b=>b.addEventListener('click', ()=>{
    escState.catFundo = b.dataset.catfundo; renderPainelGaleria();
  }));
  box.querySelectorAll('[data-fundo]').forEach(b=>b.addEventListener('click', ()=>{
    const [c,i] = b.dataset.fundo.split('|');
    escState.fundo = fundoPorRef({ cat:c, i:Number(i) });
    renderEscrever();
  }));
  document.getElementById('escFundoLimpar').addEventListener('click', ()=>{
    escState.fundo = null; renderEscrever();
  });
}

/* ---------------- painel: música ---------------- */
function renderPainelMusica(){
  const box = document.getElementById('escPainel');
  const q = normTexto(escState.buscaMus);
  const lista = TRILHAS.filter(t => !q ||
    normTexto(t.nome).includes(q) || normTexto(t.genero).includes(q) || normTexto(t.humor).includes(q));
  const sel = escState.musica;

  box.innerHTML = `
  <div class="esc-panel">
    <div class="esc-panel-head"><b>Música do relato</b>
      <button class="ao-back" id="escMusUpload">Usar música do aparelho</button>
    </div>
    <div class="mus-search">
      <input type="text" id="escMusBusca" placeholder="Pesquisar por nome, gênero ou clima (ex.: piano, calma, coragem)" value="${escapeHtml(escState.buscaMus)}">
    </div>
    <div class="mus-list">
      ${lista.length ? lista.map(t=>`
        <button class="mus-item ${sel && sel.id===t.id ? 'on':''}" data-trilha="${t.id}">
          <span class="mus-play">${f5svg('play',14,'currentColor',0)}</span>
          <span class="mus-meta"><b>${escapeHtml(t.nome)}</b><small>${escapeHtml(t.genero)} · ${escapeHtml(t.humor)} · ${fmtSeg(t.dur)}</small></span>
        </button>`).join('')
      : `<p class="ao-hint">Nenhuma trilha com esse termo.</p>`}
    </div>
    ${sel ? `
    <div class="mus-trim">
      <label>Escolha a parte da música</label>
      <div class="mus-range">
        <span style="min-width:52px;text-align:left;font-size:12px;font-weight:700;">Início</span>
        <input type="range" id="musDe" min="0" max="${Math.max(1, Math.floor(sel.dur||60))}" step="1" value="${Math.floor(sel.de||0)}">
        <span>${fmtSeg(sel.de)}</span>
      </div>
      <div class="mus-range">
        <span style="min-width:52px;text-align:left;font-size:12px;font-weight:700;">Fim</span>
        <input type="range" id="musAte" min="1" max="${Math.max(2, Math.floor(sel.dur||60))}" step="1" value="${Math.floor(sel.ate|| Math.min(30, sel.dur||30))}">
        <span>${fmtSeg(sel.ate)}</span>
      </div>
      <button class="ao-btn" id="musPreview" style="max-width:220px;">Ouvir este trecho</button>
    </div>` : `<p class="ao-hint" style="margin-top:10px;">Escolha uma trilha para poder recortar o trecho que quiser.</p>`}
  </div>`;

  const busca = document.getElementById('escMusBusca');
  let tm=null;
  busca.addEventListener('input', ()=>{ escState.buscaMus = busca.value; clearTimeout(tm); tm=setTimeout(()=>{ renderPainelMusica(); document.getElementById('escMusBusca').focus(); }, 200); });

  box.querySelectorAll('[data-trilha]').forEach(b=>b.addEventListener('click', ()=>{
    const tr = TRILHAS.find(t=>t.id===b.dataset.trilha);
    escState.musica = { tipo:'trilha', id:tr.id, nome:tr.nome, dur:tr.dur, de:0, ate:Math.min(30,tr.dur), persistir:true };
    renderEscrever();
  }));
  const de = document.getElementById('musDe'), ate = document.getElementById('musAte');
  if(de) de.addEventListener('input', ()=>{
    escState.musica.de = Math.min(Number(de.value), (escState.musica.ate||0) - 3);
    if(escState.musica.de < 0) escState.musica.de = 0;
    renderPainelMusica();
  });
  if(ate) ate.addEventListener('input', ()=>{
    escState.musica.ate = Math.max(Number(ate.value), (escState.musica.de||0) + 3);
    renderPainelMusica();
  });
  const pv = document.getElementById('musPreview');
  if(pv) pv.addEventListener('click', ()=>{
    if(Musica.tocando){ Musica.parar(); pv.textContent='Ouvir este trecho'; return; }
    pv.textContent = 'Parar';
    Musica.tocarRef(escState.musica, ()=>{ const b=document.getElementById('musPreview'); if(b) b.textContent='Ouvir este trecho'; });
  });
  document.getElementById('escMusUpload').addEventListener('click', ()=>document.getElementById('escAudioFile').click());
  document.getElementById('escAudioFile').addEventListener('change', (e)=>{
    const f = e.target.files && e.target.files[0];
    e.target.value = '';
    if(!f) return;
    const url = URL.createObjectURL(f);
    const a = new Audio(url);
    a.addEventListener('loadedmetadata', ()=>{
      const dur = isFinite(a.duration) ? a.duration : 60;
      const grava = f.size <= 900*1024;
      const aplica = (src, persistir)=>{
        escState.musica = { tipo:'arquivo', id:'up_'+Date.now(), nome:f.name.replace(/\.[^.]+$/,''), dur, de:0, ate:Math.min(30,dur), src, persistir };
        renderEscrever();
      };
      if(grava){
        const fr = new FileReader();
        fr.onload = ()=>aplica(fr.result, true);
        fr.onerror = ()=>aplica(url, false);
        fr.readAsDataURL(f);
      }else{
        aplica(url, false);
        toast('Áudio grande: ele toca agora, mas não fica guardado. Recorte um trecho curto para salvar.', 4200);
      }
    }, { once:true });
  });
}

/* ================================================================
   EDITOR DE FOTO E VÍDEO
   Recorte, luz, contraste, saturação, temperatura, desfoque,
   vinheta, texto sobre a mídia com escolha de fonte, tamanho, cor
   e posição. Vídeo ganha ainda corte de início e fim.
   ================================================================ */
const edState = {
  tipo:'imagem', src:null, img:null, videoEl:null,
  zoom:1, ox:0, oy:0, prop:'orig',
  brilho:100, contraste:100, satur:100, temp:0, desfoque:0, vinheta:0,
  texto:'', fonte:'display', tamanho:44, cor:'#FFFFFF', pos:'baixo',
  vDe:0, vAte:0, arquivo:null,
};
const ED_FONTES = [
  { id:'display', label:'Serifada',   css:"600 {S}px 'Fraunces', Georgia, serif" },
  { id:'body',    label:'Padrão',     css:"800 {S}px 'Manrope', sans-serif" },
  { id:'hand',    label:'Manuscrita', css:"700 {S}px 'Caveat', cursive" },
  { id:'mono',    label:'Máquina',    css:"700 {S}px ui-monospace, 'Courier New', monospace" },
];
const ED_CORES = ['#FFFFFF','#1B1817','#FFD166','#FF6B35','#0B8A6E','#7C3AED','#E6399B','#F4E9CE'];

function edFiltroCSS(){
  const t = edState.temp;
  const sep = t > 0 ? `sepia(${Math.min(100,t)/160})` : '';
  const hue = t < 0 ? `hue-rotate(${t*0.5}deg)` : '';
  return `brightness(${edState.brilho}%) contrast(${edState.contraste}%) saturate(${edState.satur}%) blur(${edState.desfoque}px) ${sep} ${hue}`.trim();
}

function abrirEditorMidia(file, existente){
  let ov = document.getElementById('medOverlay');
  if(!ov){
    ov = document.createElement('div');
    ov.className = 'med-overlay'; ov.id = 'medOverlay';
    document.body.appendChild(ov);
  }
  const prep = (tipo, src)=>{
    Object.assign(edState, {
      tipo, src, zoom:1, ox:0, oy:0, prop:'orig',
      brilho:100, contraste:100, satur:100, temp:0, desfoque:0, vinheta:0,
      texto:'', fonte:'display', tamanho:44, cor:'#FFFFFF', pos:'baixo', vDe:0, vAte:0,
      arquivo:file || null,
    });
    if(existente && existente.ed) Object.assign(edState, existente.ed, { tipo, src, arquivo:null });
    edState.img = null;
    ov.classList.add('show');
    lockScroll();
    /* os controles aparecem na hora; a imagem entra no quadro assim
       que terminar de carregar, para a tela nunca ficar vazia */
    renderEditor();
    if(tipo === 'imagem'){
      const img = new Image();
      img.onload = ()=>{ edState.img = img; desenharEditor(); };
      img.onerror = ()=>toast('Não foi possível abrir esta imagem.');
      img.src = src;
    }
  };

  if(existente){
    prep(existente.tipo, existente.src);
    return;
  }
  const tipo = file.type.startsWith('video') ? 'video' : 'imagem';
  if(file.size > 12*1024*1024 && tipo==='imagem'){ toast('Imagem muito grande. Escolha outra até 12 MB.'); return; }
  const url = URL.createObjectURL(file);
  if(tipo === 'imagem'){
    const fr = new FileReader();
    fr.onload = ()=>prep('imagem', fr.result);
    fr.onerror = ()=>prep('imagem', url);
    fr.readAsDataURL(file);
  }else{
    prep('video', url);
  }
}
function fecharEditor(){
  const ov = document.getElementById('medOverlay');
  if(ov) ov.classList.remove('show');
  unlockScroll();
}

function renderEditor(){
  const ov = document.getElementById('medOverlay');
  if(!ov) return;
  const ehVideo = edState.tipo === 'video';
  ov.innerHTML = `
  <div class="med-box">
    <div>
      <div class="med-stage" id="medStage">
        ${ehVideo
          ? `<video id="medVideo" src="${edState.src}" controls playsinline style="filter:${edFiltroCSS()}"></video>`
          : `<canvas id="medCanvas"></canvas>`}
      </div>
      <p class="med-tip" style="margin-top:8px;">${ehVideo
        ? 'Arraste os cortes para escolher o trecho. Os ajustes de luz, cor e texto são aplicados na exibição do relato.'
        : 'Arraste a imagem para reposicionar e use o zoom para recortar.'}</p>
    </div>

    <div class="med-side">
      <div class="med-title">${ehVideo ? 'Editar vídeo' : 'Editar foto'}</div>

      ${ehVideo ? `
      <div class="med-group">
        <b>${f5svg('cortar',13)} Corte do vídeo</b>
        <div class="med-row"><label>Início</label><input type="range" id="edVDe" min="0" max="100" value="0"><output id="outVDe">0:00</output></div>
        <div class="med-row"><label>Fim</label><input type="range" id="edVAte" min="0" max="100" value="100"><output id="outVAte">—</output></div>
      </div>` : `
      <div class="med-group">
        <b>${f5svg('cortar',13)} Recorte</b>
        <div class="med-chips" style="margin-bottom:9px;">
          ${[['orig','Original'],['1:1','Quadrado'],['4:5','Retrato'],['16:9','Paisagem'],['9:16','Story']]
            .map(([k,l])=>`<button class="med-chip ${edState.prop===k?'on':''}" data-prop="${k}">${l}</button>`).join('')}
        </div>
        <div class="med-row"><label>Zoom</label><input type="range" id="edZoom" min="100" max="320" value="${Math.round(edState.zoom*100)}"><output>${Math.round(edState.zoom*100)}%</output></div>
        <button class="med-chip" id="edCentrar">Centralizar</button>
      </div>`}

      <div class="med-group">
        <b>Luz e cor</b>
        <div class="med-row"><label>Brilho</label><input type="range" id="edBrilho" min="40" max="180" value="${edState.brilho}"><output>${edState.brilho}</output></div>
        <div class="med-row"><label>Contraste</label><input type="range" id="edContraste" min="40" max="200" value="${edState.contraste}"><output>${edState.contraste}</output></div>
        <div class="med-row"><label>Saturação</label><input type="range" id="edSatur" min="0" max="220" value="${edState.satur}"><output>${edState.satur}</output></div>
        <div class="med-row"><label>Temperatura</label><input type="range" id="edTemp" min="-60" max="100" value="${edState.temp}"><output>${edState.temp}</output></div>
        <div class="med-row"><label>Desfoque</label><input type="range" id="edDesfoque" min="0" max="12" value="${edState.desfoque}"><output>${edState.desfoque}</output></div>
        <div class="med-row"><label>Vinheta</label><input type="range" id="edVinheta" min="0" max="100" value="${edState.vinheta}"><output>${edState.vinheta}</output></div>
      </div>

      <div class="med-group">
        <b>${f5svg('texto',13)} Escrever sobre a mídia</b>
        <input type="text" class="med-input" id="edTexto" maxlength="140" placeholder="Escreva algo sobre a imagem…" value="${escapeHtml(edState.texto)}">
        <div class="med-chips" style="margin:9px 0;">
          ${ED_FONTES.map(f=>`<button class="med-chip ${edState.fonte===f.id?'on':''}" data-edfonte="${f.id}">${f.label}</button>`).join('')}
        </div>
        <div class="med-row"><label>Tamanho</label><input type="range" id="edTam" min="18" max="96" value="${edState.tamanho}"><output>${edState.tamanho}</output></div>
        <div class="med-colors" style="margin-bottom:9px;">
          ${ED_CORES.map(c=>`<button class="med-color ${edState.cor===c?'on':''}" data-edcor="${c}" style="background:${c}" aria-label="Cor ${c}"></button>`).join('')}
        </div>
        <div class="med-chips">
          ${[['topo','Topo'],['centro','Centro'],['baixo','Base']].map(([k,l])=>`<button class="med-chip ${edState.pos===k?'on':''}" data-edpos="${k}">${l}</button>`).join('')}
        </div>
      </div>

      <div class="med-foot">
        <button class="btn btn-coral" id="edAplicar">Aplicar ao relato</button>
        <button class="btn btn-outline" id="edCancelar">Cancelar</button>
      </div>
      <p class="med-tip">Nada é enviado para fora do seu aparelho: a edição acontece no próprio navegador.</p>
    </div>
  </div>`;

  wireEditor();
  if(!ehVideo) desenharEditor();
}

function wireEditor(){
  const ov = document.getElementById('medOverlay');
  const liga = (id, campo, transf)=>{
    const el = document.getElementById(id);
    if(!el) return;
    el.addEventListener('input', ()=>{
      edState[campo] = transf ? transf(el.value) : Number(el.value);
      const out = el.parentElement.querySelector('output');
      if(out) out.textContent = el.id==='edZoom' ? Math.round(edState.zoom*100)+'%' : edState[campo];
      if(edState.tipo==='imagem') desenharEditor();
      else { const v = document.getElementById('medVideo'); if(v) v.style.filter = edFiltroCSS(); }
    });
  };
  liga('edZoom','zoom', v=>Number(v)/100);
  liga('edBrilho','brilho'); liga('edContraste','contraste'); liga('edSatur','satur');
  liga('edTemp','temp'); liga('edDesfoque','desfoque'); liga('edVinheta','vinheta');
  liga('edTam','tamanho');

  ov.querySelectorAll('[data-prop]').forEach(b=>b.addEventListener('click', ()=>{
    edState.prop = b.dataset.prop;
    ov.querySelectorAll('[data-prop]').forEach(x=>x.classList.toggle('on', x===b));
    desenharEditor();
  }));
  ov.querySelectorAll('[data-edfonte]').forEach(b=>b.addEventListener('click', ()=>{
    edState.fonte = b.dataset.edfonte;
    ov.querySelectorAll('[data-edfonte]').forEach(x=>x.classList.toggle('on', x===b));
    if(edState.tipo==='imagem') desenharEditor();
  }));
  ov.querySelectorAll('[data-edcor]').forEach(b=>b.addEventListener('click', ()=>{
    edState.cor = b.dataset.edcor;
    ov.querySelectorAll('[data-edcor]').forEach(x=>x.classList.toggle('on', x===b));
    if(edState.tipo==='imagem') desenharEditor();
  }));
  ov.querySelectorAll('[data-edpos]').forEach(b=>b.addEventListener('click', ()=>{
    edState.pos = b.dataset.edpos;
    ov.querySelectorAll('[data-edpos]').forEach(x=>x.classList.toggle('on', x===b));
    if(edState.tipo==='imagem') desenharEditor();
  }));
  const txt = document.getElementById('edTexto');
  if(txt) txt.addEventListener('input', ()=>{ edState.texto = txt.value; if(edState.tipo==='imagem') desenharEditor(); });
  const cen = document.getElementById('edCentrar');
  if(cen) cen.addEventListener('click', ()=>{ edState.ox=0; edState.oy=0; edState.zoom=1;
    const z=document.getElementById('edZoom'); if(z) z.value=100; desenharEditor(); });

  /* arrastar para reposicionar */
  const cv = document.getElementById('medCanvas');
  if(cv){
    let arrastando=false, px=0, py=0;
    const start = (x,y)=>{ arrastando=true; px=x; py=y; };
    const move = (x,y)=>{
      if(!arrastando) return;
      edState.ox += (x-px); edState.oy += (y-py); px=x; py=y; desenharEditor();
    };
    const end = ()=>{ arrastando=false; };
    cv.addEventListener('pointerdown', e=>{ cv.setPointerCapture(e.pointerId); start(e.clientX,e.clientY); });
    cv.addEventListener('pointermove', e=>move(e.clientX,e.clientY));
    cv.addEventListener('pointerup', end);
    cv.addEventListener('pointercancel', end);
  }

  /* corte do vídeo */
  const v = document.getElementById('medVideo');
  if(v){
    v.addEventListener('loadedmetadata', ()=>{
      const dur = isFinite(v.duration) ? v.duration : 0;
      if(!edState.vAte) edState.vAte = dur;
      const de = document.getElementById('edVDe'), ate = document.getElementById('edVAte');
      de.max = Math.floor(dur); ate.max = Math.floor(dur);
      de.value = Math.floor(edState.vDe); ate.value = Math.floor(edState.vAte);
      document.getElementById('outVDe').textContent = fmtSeg(edState.vDe);
      document.getElementById('outVAte').textContent = fmtSeg(edState.vAte);
    }, { once:true });
    const de = document.getElementById('edVDe'), ate = document.getElementById('edVAte');
    if(de) de.addEventListener('input', ()=>{
      edState.vDe = Math.min(Number(de.value), edState.vAte-1);
      document.getElementById('outVDe').textContent = fmtSeg(edState.vDe);
      v.currentTime = edState.vDe;
    });
    if(ate) ate.addEventListener('input', ()=>{
      edState.vAte = Math.max(Number(ate.value), edState.vDe+1);
      document.getElementById('outVAte').textContent = fmtSeg(edState.vAte);
    });
  }

  document.getElementById('edCancelar').addEventListener('click', fecharEditor);
  document.getElementById('edAplicar').addEventListener('click', aplicarEdicao);
  ov.addEventListener('click', e=>{ if(e.target === ov) fecharEditor(); });
}

function edProporcao(){
  const p = edState.prop;
  if(p === '1:1') return 1;
  if(p === '4:5') return 4/5;
  if(p === '16:9') return 16/9;
  if(p === '9:16') return 9/16;
  return null;
}
function desenharEditor(){
  const cv = document.getElementById('medCanvas');
  if(!cv || !edState.img) return;
  const img = edState.img;
  const razao = edProporcao();
  const LARG = 1080;
  let w = LARG, h = razao ? Math.round(LARG/razao) : Math.round(LARG * img.height / img.width);
  h = Math.min(h, 1620);
  cv.width = w; cv.height = h;
  const maxCss = Math.min(560, window.innerWidth - 80);
  cv.style.width = maxCss + 'px';
  cv.style.height = Math.round(maxCss * h / w) + 'px';

  const ctx = cv.getContext('2d');
  ctx.clearRect(0,0,w,h);
  ctx.save();
  ctx.filter = edFiltroCSS();
  const escala = Math.max(w/img.width, h/img.height) * edState.zoom;
  const dw = img.width*escala, dh = img.height*escala;
  const fator = w / maxCss;
  const dx = (w-dw)/2 + edState.ox*fator, dy = (h-dh)/2 + edState.oy*fator;
  ctx.drawImage(img, dx, dy, dw, dh);
  ctx.restore();

  /* vinheta */
  if(edState.vinheta > 0){
    const g = ctx.createRadialGradient(w/2,h/2,Math.min(w,h)*0.25, w/2,h/2,Math.max(w,h)*0.72);
    g.addColorStop(0,'rgba(0,0,0,0)');
    g.addColorStop(1,`rgba(0,0,0,${edState.vinheta/100*0.85})`);
    ctx.fillStyle = g; ctx.fillRect(0,0,w,h);
  }

  /* texto */
  if(edState.texto.trim()){
    const f = ED_FONTES.find(x=>x.id===edState.fonte) || ED_FONTES[0];
    const tam = edState.tamanho * (w/1080) * 1.6;
    ctx.font = f.css.replace('{S}', Math.round(tam));
    ctx.textAlign = 'center';
    ctx.fillStyle = edState.cor;
    ctx.shadowColor = 'rgba(0,0,0,.55)'; ctx.shadowBlur = tam*0.32; ctx.shadowOffsetY = tam*0.06;
    const linhas = quebrarTexto(ctx, edState.texto.trim(), w*0.84);
    const alturaLinha = tam*1.24;
    let y;
    if(edState.pos === 'topo') y = h*0.14 + alturaLinha;
    else if(edState.pos === 'centro') y = h/2 - (linhas.length-1)*alturaLinha/2 + alturaLinha*0.32;
    else y = h*0.9 - (linhas.length-1)*alturaLinha;
    linhas.forEach((l,i)=>ctx.fillText(l, w/2, y + i*alturaLinha));
    ctx.shadowBlur = 0; ctx.shadowOffsetY = 0;
  }
}
function quebrarTexto(ctx, texto, max){
  const palavras = texto.split(/\s+/);
  const linhas = []; let atual = '';
  palavras.forEach(p=>{
    const teste = atual ? atual+' '+p : p;
    if(ctx.measureText(teste).width > max && atual){ linhas.push(atual); atual = p; }
    else atual = teste;
  });
  if(atual) linhas.push(atual);
  return linhas.slice(0,6);
}

function aplicarEdicao(){
  if(edState.tipo === 'imagem'){
    const cv = document.getElementById('medCanvas');
    if(!cv){ fecharEditor(); return; }
    let dataURL = cv.toDataURL('image/jpeg', 0.82);
    if(dataURL.length > 1.6*1024*1024) dataURL = cv.toDataURL('image/jpeg', 0.62);
    escState.media = { tipo:'imagem', src:dataURL, filtro:'none', persistir: dataURL.length < 2.4*1024*1024,
      ed:{ brilho:edState.brilho, contraste:edState.contraste, satur:edState.satur, temp:edState.temp,
           desfoque:edState.desfoque, vinheta:edState.vinheta, texto:edState.texto, fonte:edState.fonte,
           tamanho:edState.tamanho, cor:edState.cor, pos:edState.pos, prop:edState.prop, zoom:edState.zoom } };
  }else{
    const persistivel = edState.arquivo && edState.arquivo.size <= 2.4*1024*1024;
    const aplica = (src, persistir)=>{
      escState.media = { tipo:'video', src, filtro:edFiltroCSS(), persistir,
        vDe:edState.vDe, vAte:edState.vAte, legenda:edState.texto,
        legFonte:edState.fonte, legCor:edState.cor, legPos:edState.pos, legTam:edState.tamanho,
        ed:{ brilho:edState.brilho, contraste:edState.contraste, satur:edState.satur, temp:edState.temp,
             desfoque:edState.desfoque, vinheta:edState.vinheta, texto:edState.texto, fonte:edState.fonte,
             tamanho:edState.tamanho, cor:edState.cor, pos:edState.pos, vDe:edState.vDe, vAte:edState.vAte } };
      fecharEditor(); renderEscrever();
    };
    if(persistivel){
      const fr = new FileReader();
      fr.onload = ()=>aplica(fr.result, true);
      fr.onerror = ()=>aplica(edState.src, false);
      fr.readAsDataURL(edState.arquivo);
      return;
    }
    if(edState.arquivo) toast('Vídeo grande: ele aparece nesta sessão, mas não fica guardado.', 4200);
    aplica(edState.src, false);
    return;
  }
  fecharEditor();
  renderEscrever();
}

/* ================================================================
   ENVIO DO RELATO — publicar na comunidade ou guardar para si
   Mídia e áudio ficam em chaves próprias, para não estourar o
   limite da chave do feed.
   ================================================================ */
const _midiaCache = new Map();
async function guardarMidia(id, media, compartilhado){
  if(!media || media.persistir === false) return null;
  const chave = (compartilhado ? 'midia:' : 'pmidia:') + id;
  const payload = { tipo:media.tipo, src:media.src, filtro:media.filtro||'none',
    legenda:media.legenda||'', legFonte:media.legFonte, legCor:media.legCor, legPos:media.legPos,
    vDe:media.vDe||0, vAte:media.vAte||0 };
  _midiaCache.set(chave, payload);
  const ok = await dbSet(chave, payload, compartilhado);
  return ok ? chave : null;
}
async function carregarMidia(chave, compartilhado){
  if(!chave) return null;
  if(_midiaCache.has(chave)) return _midiaCache.get(chave);
  const v = await dbGet(chave, compartilhado);
  if(v) _midiaCache.set(chave, v);
  return v;
}

async function enviarRelato(destino){
  const texto = (escState.texto || '').trim();
  if(!texto && !escState.media && !escState.quote){
    toast('Escreva algo, escolha uma mídia ou anexe uma frase antes de salvar.');
    return;
  }
  if(texto && containsBadWords(texto)){
    toast('Seu texto contém linguagem imprópria e não foi enviado. Por favor, revise.', 4200);
    return;
  }
  const id = uid(destino === 'comunidade' ? 'post' : 'mp');
  const compartilhado = destino === 'comunidade';
  const chaveMidia = escState.media ? await guardarMidia(id, escState.media, compartilhado) : null;

  const musica = escState.musica ? {
    tipo: escState.musica.tipo, id: escState.musica.id, nome: escState.musica.nome,
    de: escState.musica.de, ate: escState.musica.ate, dur: escState.musica.dur,
    src: (escState.musica.persistir && escState.musica.tipo==='arquivo') ? escState.musica.src : null,
  } : null;

  const comum = {
    id, text: texto,
    font: escState.fonte, color: escState.cor,
    fundo: escState.fundo ? { cat:escState.fundo.cat, i:escState.fundo.i } : null,
    midia: chaveMidia,
    midiaSessao: (escState.media && !chaveMidia) ? escState.media : null,
    musica,
    quote: escState.quote ? { text:escState.quote.text, author:escState.quote.author, idx:escState.quote.idx } : null,
    createdAt: Date.now(),
  };

  if(compartilhado){
    const post = Object.assign({}, comum, {
      authorEmail: state.currentUser.email,
      authorUsername: state.currentUser.username,
      likes:[], comments:[], reports:[], hidden:false, arq:false, del:false,
    });
    state.communityPosts.unshift(post);
    if(state.communityPosts.length > 240) state.communityPosts.length = 240;
    await saveCommunityPosts();
    toast('Publicado na comunidade');
    limparEscrever();
    navigateTo('comunidade');
  }else{
    state.myPhrases.unshift(Object.assign({}, comum, { arq:false, del:false }));
    await saveMyPhrases();
    toast('Guardado nos seus relatos pessoais');
    limparEscrever();
    navigateTo('perfil');
  }
}
function limparEscrever(){
  Musica.parar();
  escState.texto=''; escState.media=null; escState.musica=null; escState.quote=null;
  escState.fundo=null; escState.painel=null;
  renderEscrever();
}

/* atalho: comentar a partir de uma frase expandida */
function comentarFrase(idx){
  const q = QUOTES[idx];
  if(!q) return;
  escState.quote = { text:q.text, author:q.author, idx };
  escState.painel = null;
  closeQuoteModal();
  navigateTo('escrever');
  setTimeout(()=>{ const t = document.getElementById('escTexto'); if(t) t.focus(); }, 320);
}

/* ================================================================
   RENDERIZAÇÃO DOS RELATOS (comunidade e pessoais)
   ================================================================ */
function relatoFundoCSS(p){
  const f = fundoPorRef(p.fundo);
  if(f) return f.css;
  const c = STYLE_COLORS.find(x=>x.id===p.color) || STYLE_COLORS[0];
  return (state.theme === 'dark' && c.dark) ? c.dark : c.bg;
}
function relatoTinta(p){
  const f = fundoPorRef(p.fundo);
  if(f) return f.ink;
  if(p.color === 'paper') return 'var(--paper-text)';
  return state.theme === 'dark' ? '#F3ECE3' : '#1B1817';
}
function midiaHTML(p, compartilhado){
  if(p.midiaSessao){
    const m = p.midiaSessao;
    return `<div class="post-media">${m.tipo==='video'
      ? `<video src="${m.src}" muted loop playsinline autoplay style="filter:${m.filtro||'none'}"></video>`
      : `<img src="${m.src}" alt="" style="filter:${m.filtro||'none'}">`}</div><div class="post-media-scrim"></div>`;
  }
  if(p.midia) return `<div class="post-media" data-midia="${escapeHtml(p.midia)}" data-shared="${compartilhado?1:0}"></div><div class="post-media-scrim"></div>`;
  return '';
}
async function hidratarMidias(scope){
  const alvos = scope.querySelectorAll('[data-midia]:not([data-carregada])');
  for(const el of alvos){
    el.dataset.carregada = '1';
    const m = await carregarMidia(el.dataset.midia, el.dataset.shared === '1');
    if(!m) continue;
    el.innerHTML = m.tipo === 'video'
      ? `<video src="${m.src}" muted loop playsinline autoplay style="filter:${m.filtro||'none'}"></video>`
      : `<img src="${m.src}" alt="" style="filter:${m.filtro||'none'}">`;
  }
}
function quoteRefHTML(p){
  if(!p.quote) return '';
  return `<div class="post-quote-ref">
    <p>&ldquo;${escapeHtml(p.quote.text)}&rdquo;</p>
    <span>— ${escapeHtml(p.quote.author)}</span>
  </div>`;
}
function volumeHTML(p){
  if(!p.musica) return '';
  return `<button class="post-vol" data-vol="${p.id}" aria-label="Ativar som do relato" title="Tocar a música deste relato">${f5svg('mudo',18)}</button>
    <span class="post-music-name">${f5svg('nota',12)} ${escapeHtml(p.musica.nome)}</span>`;
}

/* ---- cartão da comunidade (substitui a versão anterior) ---- */
function postCardHTML(post){
  const font = STYLE_FONTS.find(f=>f.id===post.font) || STYLE_FONTS[0];
  const liked = state.currentUser && (post.likes||[]).includes(state.currentUser.email);
  const saved = state.favorites.some(f=>f.type==='post' && f.id===post.id);
  const isMe = state.currentUser && post.authorEmail===state.currentUser.email;
  const isFollowing = state.following.includes(post.authorUsername);
  const temMedia = !!(post.midia || post.midiaSessao);
  return `
  <article class="post-card reveal in-view" data-post-id="${post.id}">
    <div class="post-head">
      <div class="post-avatar" style="background:${colorForName(post.authorUsername)}">${initials(post.authorUsername)}</div>
      <div class="post-meta">
        <div class="post-username">@${escapeHtml(post.authorUsername)}</div>
        <div class="post-time">${timeAgo(post.createdAt)}</div>
      </div>
      ${!isMe
        ? `<button class="btn btn-sm ${isFollowing?'btn-ghost':'btn-outline'} follow-btn" data-follow="${escapeHtml(post.authorUsername)}">${isFollowing?'Seguindo':'Seguir'}</button>`
        : `<div class="post-own-tools">
             <button data-arq="${post.id}">${post.arq?'Desarquivar':'Arquivar'}</button>
             <button data-del="${post.id}">Excluir</button>
           </div>`}
    </div>
    <div class="post-content ${temMedia?'with-media':''} ${post.musica?'has-music':''}" data-style="${escapeHtml(post.color||'coral')}"
         style="background:${relatoFundoCSS(post)}; background-size:cover; color:${relatoTinta(post)};">
      ${midiaHTML(post, true)}
      ${volumeHTML(post)}
      <div style="position:relative; z-index:2; width:100%;">
        ${quoteRefHTML(post)}
        ${post.text ? `<p class="post-text" style="font-family:${font.family}; color:inherit;">${escapeHtml(post.text)}</p>` : ''}
      </div>
    </div>
    <div class="post-actions">
      <button class="action-btn ${liked?'liked':''}" data-like="${post.id}">
        <svg viewBox="0 0 24 24" fill="${liked?'currentColor':'none'}" stroke="currentColor" stroke-width="2" stroke-linejoin="round">${F5_ICONS.coracao}</svg>
        ${(post.likes||[]).length||''}
      </button>
      <button class="action-btn" data-comment-toggle="${post.id}">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round">${F5_ICONS.balao}</svg>
        ${(post.comments||[]).length||''}
      </button>
      <button class="action-btn" data-share="${post.id}">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8.6 10.6 6.8-3.8M8.6 13.4l6.8 3.8"/></svg>
      </button>
      <button class="action-btn ${saved?'saved':''}" data-save-post="${post.id}">
        <svg viewBox="0 0 24 24" fill="${saved?'currentColor':'none'}" stroke="currentColor" stroke-width="2" stroke-linejoin="round">${F5_ICONS.salvar}</svg>
      </button>
      <button class="action-btn report-btn action-spacer" data-report="${post.id}" aria-label="Denunciar" title="Denunciar conteúdo">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 15V4l1.5-1 2 1.5h9L15 6l3-2v10l-2 1.5h-9L5.5 14 4 15Z"/><path d="M4 15v6"/></svg>
      </button>
    </div>
    <div class="comment-section hidden" id="comments-${post.id}">
      <div class="comment-list">
        ${(post.comments||[]).map(c=>`<div class="comment">
            <div class="comment-avatar" style="background:${colorForName(c.username)}; display:flex;align-items:center;justify-content:center;color:#fff;font-size:10px;font-weight:800;">${initials(c.username)}</div>
            <div><b>@${escapeHtml(c.username)}</b> <span style="color:var(--text-soft)">${escapeHtml(c.text)}</span></div>
          </div>`).join('') || `<p style="font-size:13px;color:var(--text-faint);">Nenhum comentário ainda.</p>`}
      </div>
      ${state.currentUser ? `<div class="comment-input-row">
        <input type="text" class="comment-input" id="commentInput-${post.id}" placeholder="Escreva um comentário…" maxlength="220">
        <button class="btn-icon" data-comment-send="${post.id}" aria-label="Enviar comentário">
          <svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m3 20 18-8L3 4v6l13 2-13 2v6Z"/></svg>
        </button>
      </div>` : ''}
    </div>
  </article>`;
}

/* ---- eventos do feed (acrescenta som, arquivar e excluir) ----
   Guarda a versão anterior e a estende. Aqui não pode existir uma
   segunda declaração `function attachPostEvents`: como declarações
   de função sobem para o topo do escopo, a referência guardada
   apontaria para ela mesma e entraria em recursão infinita. */
const _attachPostEventsBase = attachPostEvents;
function attachPostEventsF5(container){
  _attachPostEventsBase(container);
  container.querySelectorAll('[data-vol]:not([data-wired])').forEach(b=>{
    b.dataset.wired = '1';
    b.addEventListener('click', (e)=>{
      e.stopPropagation();
      const id = b.dataset.vol;
      const p = state.communityPosts.find(x=>x.id===id) || state.myPhrases.find(x=>x.id===id);
      if(!p || !p.musica) return;
      if(Musica.estaTocando(p.musica.tipo==='trilha' ? p.musica.id : p.musica.src)){
        Musica.parar(); marcarVolume(b, false); return;
      }
      document.querySelectorAll('.post-vol.on').forEach(x=>marcarVolume(x,false));
      const ok = Musica.tocarRef(p.musica, ()=>marcarVolume(b,false));
      if(ok) marcarVolume(b, true);
    });
  });
  container.querySelectorAll('[data-arq]:not([data-wired])').forEach(b=>{
    b.dataset.wired = '1';
    b.addEventListener('click', ()=>arquivarRelato(b.dataset.arq));
  });
  container.querySelectorAll('[data-del]:not([data-wired])').forEach(b=>{
    b.dataset.wired = '1';
    b.addEventListener('click', ()=>excluirRelato(b.dataset.del));
  });
  hidratarMidias(container);
}
attachPostEvents = attachPostEventsF5;

function marcarVolume(btn, ligado){
  btn.classList.toggle('on', ligado);
  btn.innerHTML = f5svg(ligado ? 'som' : 'mudo', 18);
  btn.setAttribute('aria-label', ligado ? 'Desligar som do relato' : 'Ativar som do relato');
}

/* ---- arquivar / excluir / restaurar ---- */
async function arquivarRelato(id){
  const p = state.communityPosts.find(x=>x.id===id);
  if(p){ p.arq = !p.arq; await saveCommunityPosts(); toast(p.arq?'Relato arquivado':'Relato desarquivado'); }
  else{
    const m = state.myPhrases.find(x=>x.id===id);
    if(!m) return;
    m.arq = !m.arq; await saveMyPhrases(); toast(m.arq?'Relato arquivado':'Relato desarquivado');
  }
  atualizarTelas();
}
async function excluirRelato(id){
  const p = state.communityPosts.find(x=>x.id===id);
  if(p){ p.del = true; p.arq = false; await saveCommunityPosts(); }
  else{
    const m = state.myPhrases.find(x=>x.id===id);
    if(!m) return;
    m.del = true; m.arq = false; await saveMyPhrases();
  }
  toast('Movido para Apagados. Você pode restaurar no seu perfil.', 3400);
  atualizarTelas();
}
async function restaurarRelato(id){
  const p = state.communityPosts.find(x=>x.id===id);
  if(p){ p.del = false; p.arq = false; await saveCommunityPosts(); }
  else{
    const m = state.myPhrases.find(x=>x.id===id);
    if(!m) return;
    m.del = false; m.arq = false; await saveMyPhrases();
  }
  toast('Relato restaurado');
  atualizarTelas();
}
async function esvaziarLixeira(){
  const meu = state.currentUser ? state.currentUser.email : null;
  if(!meu) return;
  state.communityPosts = state.communityPosts.filter(p => !(p.del && p.authorEmail===meu));
  state.myPhrases = state.myPhrases.filter(m => !m.del);
  await saveCommunityPosts();
  await saveMyPhrases();
  toast('Lixeira esvaziada');
  atualizarTelas();
}
function atualizarTelas(){
  if(state.view === 'comunidade') renderCommunityView();
  if(state.view === 'perfil') renderPerfil();
  if(state.view === 'home') renderCommunityPreview();
  if(sheetAberta) renderSheet(sheetAberta);
}

/* ================================================================
   COMUNIDADE — só os relatos das outras pessoas
   O que era escrito aqui foi migrado para o cabeçalho "Escrever".
   ================================================================ */
state.feedUser = null;
function postsVisiveis(){
  return state.communityPosts.filter(p => !p.hidden && !p.del && !p.arq);
}
function meusPosts(){
  if(!state.currentUser) return [];
  return state.communityPosts.filter(p => p.authorEmail===state.currentUser.email && !p.del && !p.arq);
}
function renderCommunityView(){
  const slot = document.getElementById('composerSlot');
  if(slot){
    slot.innerHTML = `
      <div class="com-cta">
        ${f5svg('lapis',22)}
        <p>Este espaço mostra os relatos das outras pessoas. Para escrever o seu, vá em <b>Escrever</b>.</p>
        <button class="btn btn-coral btn-sm" id="comIrEscrever">Escrever um relato</button>
      </div>`;
    const b = document.getElementById('comIrEscrever');
    if(b) b.addEventListener('click', ()=>navigateTo('escrever'));
  }

  /* filtros */
  const chips = document.getElementById('feedFilterChips');
  if(chips && !chips.dataset.f5){
    chips.dataset.f5 = '1';
    chips.innerHTML = `
      <button class="chip ${state.feedFilter==='recentes'?'active':''}" data-feed-filter="recentes">Recentes</button>
      <button class="chip ${state.feedFilter==='seguindo'?'active':''}" data-feed-filter="seguindo">Seguindo</button>`;
    chips.querySelectorAll('.chip').forEach(c=>c.addEventListener('click', ()=>{
      state.feedFilter = c.dataset.feedFilter;
      state.feedUser = null;
      chips.querySelectorAll('.chip').forEach(x=>x.classList.toggle('active', x===c));
      if(state.feedFilter === 'seguindo') requireAuth(renderCommunityView, 'Crie sua conta para ver quem você segue.');
      else renderCommunityView();
    }));
  }

  let posts = postsVisiveis();
  /* a comunidade mostra os relatos das outras pessoas */
  if(state.currentUser) posts = posts.filter(p => p.authorEmail !== state.currentUser.email);
  if(state.feedUser) posts = posts.filter(p => p.authorUsername === state.feedUser);
  else if(state.feedFilter === 'seguindo') posts = posts.filter(p => state.following.includes(p.authorUsername));

  const feedEl = document.getElementById('communityFeed');
  const emptyEl = document.getElementById('feedEmpty');
  if(!feedEl) return;

  const cabecalhoUsuario = state.feedUser
    ? `<div class="com-cta" style="border-style:solid;">
         ${f5svg('pessoa',20)}
         <p>Mostrando os relatos de <b>@${escapeHtml(state.feedUser)}</b>.</p>
         <button class="btn btn-outline btn-sm" id="comLimparUser">Ver todos</button>
       </div>` : '';

  if(posts.length === 0){
    feedEl.innerHTML = cabecalhoUsuario;
    if(emptyEl) emptyEl.classList.remove('hidden');
  }else{
    if(emptyEl) emptyEl.classList.add('hidden');
    feedEl.innerHTML = cabecalhoUsuario + posts.map(postCardHTML).join('');
    attachPostEvents(feedEl);
  }
  const lu = document.getElementById('comLimparUser');
  if(lu) lu.addEventListener('click', ()=>{ state.feedUser=null; renderCommunityView(); });

  montarDock();
}

function renderCommunityPreview(){
  const el = document.getElementById('communityPreview');
  if(!el) return;
  const posts = postsVisiveis().slice(0,2);
  el.innerHTML = posts.map(postCardHTML).join('');
  attachPostEvents(el);
}

/* ---- barra fixa: Publicados e Seguindo (sempre na tela) ---- */
function montarDock(){
  const view = document.getElementById('view-comunidade');
  if(!view) return;
  const wrap = view.querySelector('.wrap');
  let dock = document.getElementById('comDock');
  if(!dock){
    dock = document.createElement('div');
    dock.className = 'com-dock'; dock.id = 'comDock';
    wrap.appendChild(dock);
  }
  const nPub = meusPosts().length;
  const nSeg = state.following.length;
  dock.innerHTML = `
    <button data-sheet="publicados">${f5svg('publicado',17)} Publicados ${nPub?`<span class="badge">${nPub}</span>`:''}</button>
    <button data-sheet="seguindo">${f5svg('pessoas',17)} Seguindo ${nSeg?`<span class="badge">${nSeg}</span>`:''}</button>`;
  dock.querySelectorAll('[data-sheet]').forEach(b=>b.addEventListener('click', ()=>abrirSheet(b.dataset.sheet)));
}

/* ---- painéis deslizantes ---- */
let sheetAberta = null;
function abrirSheet(qual){
  sheetAberta = qual;
  let ov = document.getElementById('sheetOverlay');
  if(!ov){
    ov = document.createElement('div');
    ov.className = 'sheet-overlay'; ov.id = 'sheetOverlay';
    ov.innerHTML = `<div class="sheet" id="sheetBox"></div>`;
    document.body.appendChild(ov);
    ov.addEventListener('click', e=>{ if(e.target === ov) fecharSheet(); });
  }
  ov.classList.add('show');
  lockScroll();
  renderSheet(qual);
}
function fecharSheet(){
  const ov = document.getElementById('sheetOverlay');
  if(ov) ov.classList.remove('show');
  sheetAberta = null;
  unlockScroll();
  montarDock();
}
function renderSheet(qual){
  const box = document.getElementById('sheetBox');
  if(!box) return;
  const titulo = qual === 'publicados' ? 'Publicados' : 'Seguindo';
  let corpo = '';

  if(!state.currentUser){
    corpo = `<div class="empty-state">
      <h3>Entre para ver esta área</h3>
      <p>${qual==='publicados' ? 'Crie uma conta gratuita para publicar e acompanhar seus relatos.' : 'Crie uma conta gratuita para seguir outras pessoas.'}</p>
      <button class="btn btn-coral" style="margin-top:16px;" id="sheetLogin">Entrar ou criar conta</button>
    </div>`;
  }else if(qual === 'publicados'){
    const meus = meusPosts();
    corpo = meus.length
      ? `<div class="feed">${meus.map(postCardHTML).join('')}</div>`
      : `<div class="empty-state">
           <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6">${F5_ICONS.publicado}</svg>
           <h3>Você ainda não tem relatos publicados</h3>
           <p>Escreva o primeiro no campo Escrever e publique na comunidade.</p>
           <button class="btn btn-coral" style="margin-top:16px;" id="sheetEscrever">Escrever agora</button>
         </div>`;
  }else{
    corpo = state.following.length
      ? state.following.map(u=>`
        <div class="follow-row">
          <div class="follow-av" style="background:${colorForName(u)}">${initials(u)}</div>
          <div class="follow-meta">
            <b>@${escapeHtml(u)}</b>
            <button data-verrelatos="${escapeHtml(u)}">ver relatos</button>
          </div>
          <button class="btn btn-outline btn-sm" data-unfollow="${escapeHtml(u)}">Deixar de seguir</button>
        </div>`).join('')
      : `<div class="empty-state">
           <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6">${F5_ICONS.pessoas}</svg>
           <h3>Você ainda não segue ninguém</h3>
           <p>Toque em Seguir no cartão de alguém para acompanhar os relatos dessa pessoa.</p>
         </div>`;
  }

  box.innerHTML = `
    <div class="sheet-grab"></div>
    <div class="sheet-head">
      <h3>${titulo}</h3>
      <button class="btn-icon" id="sheetClose" aria-label="Fechar">${f5svg('fechar',20)}</button>
    </div>
    ${corpo}`;

  document.getElementById('sheetClose').addEventListener('click', fecharSheet);
  const lg = document.getElementById('sheetLogin');
  if(lg) lg.addEventListener('click', ()=>{ fecharSheet(); openAuthModal(); });
  const esc = document.getElementById('sheetEscrever');
  if(esc) esc.addEventListener('click', ()=>{ fecharSheet(); navigateTo('escrever'); });
  box.querySelectorAll('[data-unfollow]').forEach(b=>b.addEventListener('click', async ()=>{
    await toggleFollow(b.dataset.unfollow);
    renderSheet('seguindo');
  }));
  box.querySelectorAll('[data-verrelatos]').forEach(b=>b.addEventListener('click', ()=>{
    state.feedUser = b.dataset.verrelatos;
    state.feedFilter = 'recentes';
    fecharSheet();
    renderCommunityView();
    window.scrollTo({ top:0, behavior: prefersReducedMotion()?'auto':'smooth' });
  }));
  attachPostEvents(box);
}

/* ================================================================
   PERFIL — relatos, favoritos, arquivados e apagados
   ================================================================ */
function relatoPessoalHTML(p){
  const font = STYLE_FONTS.find(f=>f.id===p.font) || STYLE_FONTS[0];
  const temMedia = !!(p.midia || p.midiaSessao);
  return `
  <article class="post-card reveal in-view" data-post-id="${p.id}">
    <div class="post-head">
      <div class="post-avatar" style="background:${colorForName(state.currentUser?state.currentUser.username:'eu')}">${initials(state.currentUser?state.currentUser.username:'eu')}</div>
      <div class="post-meta">
        <div class="post-username">Relato pessoal</div>
        <div class="post-time">${timeAgo(p.createdAt)}</div>
      </div>
      <div class="post-own-tools">
        <button data-arq="${p.id}">${p.arq?'Desarquivar':'Arquivar'}</button>
        <button data-del="${p.id}">Excluir</button>
      </div>
    </div>
    <div class="post-content ${temMedia?'with-media':''} ${p.musica?'has-music':''}"
         style="background:${relatoFundoCSS(p)}; background-size:cover; color:${relatoTinta(p)};">
      ${midiaHTML(p, false)}
      ${volumeHTML(p)}
      <div style="position:relative; z-index:2; width:100%;">
        ${quoteRefHTML(p)}
        ${p.text ? `<p class="post-text" style="font-family:${font.family}; color:inherit;">${escapeHtml(p.text)}</p>` : ''}
      </div>
    </div>
  </article>`;
}
function listaArquivados(){
  const meu = state.currentUser ? state.currentUser.email : null;
  const a = state.communityPosts.filter(p=>p.arq && !p.del && p.authorEmail===meu);
  const b = state.myPhrases.filter(m=>m.arq && !m.del);
  return { posts:a, relatos:b };
}
function listaApagados(){
  const meu = state.currentUser ? state.currentUser.email : null;
  const a = state.communityPosts.filter(p=>p.del && p.authorEmail===meu);
  const b = state.myPhrases.filter(m=>m.del);
  return { posts:a, relatos:b };
}

profileTab = 'overview';   /* já declarada acima no arquivo; aqui só volta ao padrão */
function renderPerfil(){
  const el = document.getElementById('perfilContent');
  if(!el) return;
  if(!state.currentUser){
    el.innerHTML = `<div class="empty-state">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M20 21a8 8 0 1 0-16 0"/><circle cx="12" cy="7" r="4"/></svg>
      <h3>Você ainda não entrou</h3>
      <p>Crie uma conta gratuita para salvar favoritos, guardar relatos pessoais e participar da comunidade.</p>
      <button class="btn btn-coral" style="margin-top:18px;" id="perfilLoginBtn">Entrar ou criar conta</button>
    </div>`;
    document.getElementById('perfilLoginBtn').addEventListener('click', ()=>openAuthModal());
    return;
  }
  const u = state.currentUser;
  const arq = listaArquivados(), lix = listaApagados();
  const nArq = arq.posts.length + arq.relatos.length;
  const nLix = lix.posts.length + lix.relatos.length;

  el.innerHTML = `
    <div class="profile-head">
      <div class="profile-avatar" style="background:${colorForName(u.username)}">${initials(u.username)}</div>
      <div>
        <h2 style="font-family:var(--font-display); font-size:24px;">${escapeHtml(u.username)}</h2>
        <p style="color:var(--text-soft); font-size:14px;">${escapeHtml(u.email)}</p>
        <div class="profile-stats">
          <span><b>${meusPosts().length}</b> <span style="color:var(--text-faint);font-size:12.5px;">publicações</span></span>
          <span><b>${state.favorites.length}</b> <span style="color:var(--text-faint);font-size:12.5px;">favoritos</span></span>
          <span><b>${state.following.length}</b> <span style="color:var(--text-faint);font-size:12.5px;">seguindo</span></span>
        </div>
      </div>
      <button class="btn btn-outline btn-sm" id="logoutBtn" style="margin-left:auto;">Sair</button>
    </div>
    <div class="profile-tabs">
      <button class="profile-tab ${profileTab==='overview'?'active':''}" data-tab="overview">Meus relatos</button>
      <button class="profile-tab ${profileTab==='favorites'?'active':''}" data-tab="favorites">Favoritos</button>
      <button class="profile-tab ${profileTab==='arquivados'?'active':''}" data-tab="arquivados">Arquivados${nArq?` (${nArq})`:''}</button>
      <button class="profile-tab ${profileTab==='apagados'?'active':''}" data-tab="apagados">Apagados${nLix?` (${nLix})`:''}</button>
    </div>
    <div id="profileTabContent"></div>`;

  document.getElementById('logoutBtn').addEventListener('click', logout);
  el.querySelectorAll('.profile-tab').forEach(t=>t.addEventListener('click', ()=>{ profileTab=t.dataset.tab; renderPerfil(); }));
  const box = document.getElementById('profileTabContent');

  if(profileTab === 'favorites'){
    box.innerHTML = favoritesHTML();
    box.querySelectorAll('[data-fav-quote]').forEach(btn=>btn.addEventListener('click', ()=>toggleFavoriteQuote(Number(btn.dataset.favQuote)).then(renderPerfil)));
    attachPostEvents(box);
    attachQuoteCardEvents(box);
    return;
  }

  if(profileTab === 'arquivados'){
    const total = arq.posts.length + arq.relatos.length;
    box.innerHTML = total
      ? `<p class="f5-count">${total} ${total===1?'relato arquivado':'relatos arquivados'}</p>
         <div class="feed">${arq.posts.map(postCardHTML).join('')}${arq.relatos.map(relatoPessoalHTML).join('')}</div>`
      : `<div class="empty-state">
           <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6">${F5_ICONS.arquivar}</svg>
           <h3>Nada arquivado</h3>
           <p>Ao arquivar um relato, ele sai do feed e fica guardado aqui.</p>
         </div>`;
    attachPostEvents(box);
    return;
  }

  if(profileTab === 'apagados'){
    const total = lix.posts.length + lix.relatos.length;
    box.innerHTML = `
      ${total ? `<div class="trash-bar">
        <button class="btn btn-outline btn-sm" id="lixRestaurarTudo">${f5svg('restaurar',15)} Restaurar tudo</button>
        <button class="btn btn-outline btn-sm" id="lixEsvaziar">${f5svg('lixo',15)} Esvaziar a lixeira</button>
      </div>` : ''}
      ${total
        ? `<div class="feed">${[...lix.posts, ...lix.relatos].map(p=>`
            <div>
              ${p.authorUsername ? postCardHTML(p) : relatoPessoalHTML(p)}
              <div class="trash-bar" style="margin-top:-8px;">
                <button class="btn btn-coral btn-sm" data-restaurar="${p.id}">${f5svg('restaurar',15)} Restaurar</button>
              </div>
            </div>`).join('')}</div>`
        : `<div class="empty-state">
             <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6">${F5_ICONS.lixo}</svg>
             <h3>A lixeira está vazia</h3>
             <p>Relatos excluídos ficam aqui até você restaurar ou esvaziar.</p>
           </div>`}`;
    const rt = document.getElementById('lixRestaurarTudo');
    if(rt) rt.addEventListener('click', async ()=>{
      for(const p of [...lix.posts, ...lix.relatos]) { p.del = false; }
      await saveCommunityPosts(); await saveMyPhrases();
      toast('Relatos restaurados'); renderPerfil();
    });
    const ev = document.getElementById('lixEsvaziar');
    if(ev) ev.addEventListener('click', esvaziarLixeira);
    box.querySelectorAll('[data-restaurar]').forEach(b=>b.addEventListener('click', ()=>restaurarRelato(b.dataset.restaurar)));
    attachPostEvents(box);
    return;
  }

  /* aba padrão: relatos pessoais */
  const meus = state.myPhrases.filter(m=>!m.del && !m.arq);
  box.innerHTML = `
    <div class="com-cta" style="margin-top:18px;">
      ${f5svg('lapis',22)}
      <p>Seus relatos pessoais são privados. Só você vê o que está aqui.</p>
      <button class="btn btn-coral btn-sm" id="perfilEscrever">Escrever relato</button>
    </div>
    ${meus.length
      ? `<div class="feed">${meus.map(relatoPessoalHTML).join('')}</div>`
      : `<p style="color:var(--text-faint);">Nenhum relato pessoal guardado ainda.</p>`}`;
  document.getElementById('perfilEscrever').addEventListener('click', ()=>navigateTo('escrever'));
  attachPostEvents(box);
}

/* ================================================================
   CARTÃO DE FRASE EXPANDIDO
   Ganha coração, ícone de comentário e "CONHECER AUTOR" logo abaixo
   da foto e do nome — direto para o panorama, sem tela intermediária.
   ================================================================ */
function openQuoteModal(idx){
  const q = QUOTES[idx];
  if(!q) return;
  const el = document.getElementById('quoteExpand');
  const box = document.getElementById('quoteExpandBox');
  const col = colorForName(q.author);
  const isFav = isFavQuote(idx);
  const ehPessoa = !SCRIPTURE_RE.test(canonAuthor(q.author));

  box.innerHTML = `
    <button class="expand-close" id="quoteExpandClose" aria-label="Fechar frase ampliada">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><path d="M6 6l12 12M18 6L6 18"/></svg>
    </button>
    <span class="quote-card-tape" aria-hidden="true"></span>
    <div class="expand-inner">
      <span class="expand-cat">${escapeHtml(quoteCatLabel(q))}</span>
      <p class="expand-text" style="font-size:${quoteFontSize(q.text)}">&ldquo;${escapeHtml(q.text)}&rdquo;</p>
      <div class="expand-foot">
        <div class="expand-avatar" data-open-photo="${escapeHtml(q.author)}" role="button" tabindex="0" aria-label="Ampliar fotografia de ${escapeHtml(q.author)}">
          ${photoImgHTML(q.author,'card',420)}
          <div class="avatar-fallback" style="display:none; background:${col};">${initials(q.author)}</div>
        </div>
        <div class="expand-ident-wrap">
          <div class="expand-ident">
            <span class="expand-author">— ${escapeHtml(q.author)}</span>
            ${procedenciaHTML(q)}
          </div>
          ${ehPessoa ? `<button class="expand-know" id="expKnow">${f5svg('pessoa',15)} Conhecer autor</button>` : ''}
        </div>
        <div class="expand-acts">
          <button class="expand-act ${isFav?'liked':''}" id="expFav" aria-pressed="${isFav}" aria-label="Salvar frase nos favoritos" title="Favoritar">
            <svg viewBox="0 0 24 24" fill="${isFav?'currentColor':'none'}" stroke="currentColor" stroke-width="2" stroke-linejoin="round">${F5_ICONS.coracao}</svg>
          </button>
          <button class="expand-act" id="expComment" aria-label="Escrever a partir desta frase" title="Comentar / escrever">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round">${F5_ICONS.balao}</svg>
          </button>
        </div>
      </div>
    </div>`;

  el.classList.add('show');
  el.setAttribute('aria-hidden','false');
  lockScroll();
  document.getElementById('quoteExpandClose').addEventListener('click', closeQuoteModal);
  box.querySelectorAll('[data-open-photo]').forEach(b=>{
    const go = (ev)=>{ ev.stopPropagation(); openPhotoModal(b.dataset.openPhoto); };
    b.addEventListener('click', go);
    b.addEventListener('keydown', e=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); go(e); } });
  });
  const know = document.getElementById('expKnow');
  if(know) know.addEventListener('click', ()=>{ closeQuoteModal(); abrirPanorama(q.author); });
  document.getElementById('expFav').addEventListener('click', (e)=>{
    e.stopPropagation();
    requireAuth(async ()=>{
      await toggleFavoriteQuote(idx);
      const b = document.getElementById('expFav');
      if(!b) return;
      const agora = isFavQuote(idx);
      b.classList.toggle('liked', agora);
      b.setAttribute('aria-pressed', agora);
      b.querySelector('svg').setAttribute('fill', agora ? 'currentColor' : 'none');
    }, 'Crie sua conta para guardar frases nos favoritos.');
  });
  document.getElementById('expComment').addEventListener('click', (e)=>{
    e.stopPropagation();
    comentarFrase(idx);
  });
  requestAnimationFrame(()=>document.getElementById('quoteExpandClose').focus());
}

/* ================================================================
   NARRAÇÃO — vozes mais naturais e mais fáceis de entender
   ----------------------------------------------------------------
   Três problemas explicavam o som robótico e truncado:
   1. a escolha da voz pegava a primeira disponível, muitas vezes a
      pior do sistema (eSpeak) e às vezes em português europeu;
   2. o texto ia inteiro num único enunciado, e o Chrome corta a
      fala por volta de 15 segundos;
   3. abreviações, aspas e travessões eram lidos letra por letra.
   Agora a voz é escolhida por qualidade, o texto é preparado e
   dividido em frases, e há um cão de guarda contra o corte.
   ================================================================ */
const VOZ_BOA = ['natural','neural','online','premium','enhanced','wavenet','google','microsoft','siri','eloquence'];
const VOZ_FEM = ['female','feminin','mulher','maria','luciana','francisca','fernanda','joana','ines','inês','catarina','camila','vitoria','vitória','helena','isabela','leila','samantha','zira','heloisa','heloísa','yara','ana'];
const VOZ_MASC = ['male','masculin','homem','daniel','ricardo','felipe','diego','marcos','antonio','antônio','joaquim','thiago','cristiano','duarte','paulo','julio','júlio','helio','hélio','david','fabio','fábio'];

function _pontuaVoz(v, genero){
  const n = (v.name||'').toLowerCase();
  const lang = (v.lang||'').toLowerCase();
  let p = 0;
  if(lang.startsWith('pt-br') || lang === 'pt_br') p += 60;
  else if(lang.startsWith('pt')) p += 34;
  else return -1;                                   /* fora do português, descarta */
  VOZ_BOA.forEach(h=>{ if(n.includes(h)) p += 16; });
  if(v.localService === false) p += 10;             /* vozes de rede costumam ser melhores */
  if(/espeak|festival|pico|robot|compact/.test(n)) p -= 45;
  const listaG = genero === 'female' ? VOZ_FEM : VOZ_MASC;
  const listaO = genero === 'female' ? VOZ_MASC : VOZ_FEM;
  if(listaG.some(h=>n.includes(h))) p += 40;
  if(listaO.some(h=>n.includes(h))) p -= 30;
  if(v.default) p += 4;
  return p;
}
function pickVoice(voices, genderPref){
  if(!voices || !voices.length) return null;
  const pontuadas = voices.map(v=>({ v, p:_pontuaVoz(v, genderPref) })).filter(x=>x.p >= 0);
  if(pontuadas.length){
    pontuadas.sort((a,b)=>b.p-a.p);
    return pontuadas[0].v;
  }
  /* nenhum português instalado: usa o melhor disponível, sem descartar tudo */
  const alt = voices.map(v=>{
    const n = (v.name||'').toLowerCase();
    let p = 0;
    VOZ_BOA.forEach(h=>{ if(n.includes(h)) p += 12; });
    if(/espeak|pico|compact/.test(n)) p -= 25;
    if((genderPref==='female'?VOZ_FEM:VOZ_MASC).some(h=>n.includes(h))) p += 25;
    return { v, p };
  }).sort((a,b)=>b.p-a.p);
  return alt[0].v;
}

/* prepara o texto: o que estava sendo soletrado agora é falado */
const ABREV = [
  [/\bséc\.\s*/gi,'século '], [/\ba\.C\./gi,'antes de Cristo'], [/\bd\.C\./gi,'depois de Cristo'],
  [/\bSr\.\s*/g,'Senhor '], [/\bSra\.\s*/g,'Senhora '], [/\bDr\.\s*/g,'Doutor '], [/\bDra\.\s*/g,'Doutora '],
  [/\bProf\.\s*/g,'Professor '], [/\bpág\.\s*/gi,'página '], [/\bp\.\s*ex\./gi,'por exemplo'],
  [/\betc\./gi,'etcétera'], [/\bnº\s*/gi,'número '], [/\bJr\./gi,'Júnior'], [/\bSt\./gi,'Santo'],
];
function prepararNarracao(texto){
  let t = String(texto || '');
  t = t.replace(/[“”„«»"]/g,' ').replace(/[‘’]/g,"'");
  t = t.replace(/\s*[—–]\s*/g, ', ');
  t = t.replace(/\.{3,}/g, '.');
  ABREV.forEach(([re, sub])=>{ t = t.replace(re, sub); });
  t = t.replace(/\n{2,}/g, '.\n');
  t = t.replace(/\s{2,}/g, ' ').trim();
  return t;
}
function fatiarNarracao(texto, max=170){
  const partes = prepararNarracao(texto)
    .split(/(?<=[.!?:;])\s+|\n+/)
    .map(s=>s.trim()).filter(Boolean);
  const out = [];
  let atual = '';
  partes.forEach(p=>{
    /* frases muito longas são quebradas nas vírgulas */
    if(p.length > max*1.7){
      p.split(/,\s*/).forEach(sub=>{
        if((atual+' '+sub).trim().length > max){ if(atual) out.push(atual.trim()); atual = sub; }
        else atual = (atual ? atual+', ' : '') + sub;
      });
      return;
    }
    if((atual+' '+p).trim().length > max){ if(atual) out.push(atual.trim()); atual = p; }
    else atual = (atual ? atual+' ' : '') + p;
  });
  if(atual.trim()) out.push(atual.trim());
  return out;
}

let _narracao = { id:null, partes:[], i:0, cancelada:false, guarda:null, btn:null, status:null };
function _pararGuarda(){
  if(_narracao.guarda){ clearInterval(_narracao.guarda); _narracao.guarda = null; }
}
async function toggleStoryAudio(storyId, text, btn, statusEl, voiceSel){
  if(!('speechSynthesis' in window)){ toast('Seu navegador não suporta narração por voz.'); return; }

  if(_narracao.id === storyId){
    _narracao.cancelada = true;
    _pararGuarda();
    speechSynthesis.cancel();
    resetAudioUI(storyId, btn, statusEl);
    return;
  }
  _narracao.cancelada = true;
  _pararGuarda();
  speechSynthesis.cancel();
  document.querySelectorAll('.play-btn.playing').forEach(b=>{ b.classList.remove('playing'); b.innerHTML = playIconSVG(); });

  btn.innerHTML = `<svg viewBox="0 0 24 24" width="14" height="14"><rect x="3" y="3" width="18" height="18" rx="2" fill="currentColor"/></svg>`;
  btn.classList.add('playing');
  statusEl.innerHTML = `<span class="eq"><span></span><span></span><span></span></span> Preparando a narração…`;

  const voices = await loadVoices();
  const genero = voiceSel ? voiceSel.value : 'female';
  const voz = pickVoice(voices, genero);
  const partes = fatiarNarracao(text);
  if(!partes.length){ resetAudioUI(storyId, btn, statusEl); return; }

  _narracao = { id:storyId, partes, i:0, cancelada:false, guarda:null, btn, status:statusEl };
  currentAudio.id = storyId;

  const rotulo = genero === 'female' ? 'feminina' : 'masculina';
  const falar = ()=>{
    if(_narracao.cancelada || _narracao.id !== storyId) return;
    if(_narracao.i >= _narracao.partes.length){
      _pararGuarda();
      resetAudioUI(storyId, btn, statusEl);
      return;
    }
    const u = new SpeechSynthesisUtterance(_narracao.partes[_narracao.i]);
    if(voz) u.voice = voz;
    u.lang = (voz && voz.lang) || 'pt-BR';
    /* mais devagar e com altura natural: a leitura fica compreensível */
    u.rate = genero === 'female' ? 0.92 : 0.90;
    u.pitch = genero === 'female' ? 1.04 : 0.92;
    u.volume = 1;
    u.onstart = ()=>{
      const pct = Math.round((_narracao.i / _narracao.partes.length) * 100);
      statusEl.innerHTML = `<span class="eq"><span></span><span></span><span></span></span> Reproduzindo com voz ${rotulo} · ${pct}%`;
    };
    u.onend = ()=>{ _narracao.i++; setTimeout(falar, 130); };
    u.onerror = ()=>{
      if(_narracao.cancelada) return;
      _narracao.i++;
      if(_narracao.i < _narracao.partes.length) setTimeout(falar, 160);
      else { _pararGuarda(); resetAudioUI(storyId, btn, statusEl); }
    };
    currentAudio.utterance = u;
    speechSynthesis.speak(u);
  };

  /* cão de guarda: o Chrome interrompe a fala por volta de 15s */
  _narracao.guarda = setInterval(()=>{
    if(_narracao.cancelada){ _pararGuarda(); return; }
    if(speechSynthesis.speaking && !speechSynthesis.paused){
      speechSynthesis.pause(); speechSynthesis.resume();
    }
  }, 9000);

  falar();
}
function resetAudioUI(storyId, btn, statusEl){
  if(currentAudio.id===storyId) currentAudio.id = null;
  if(_narracao.id === storyId){ _narracao.id = null; _narracao.cancelada = true; }
  _pararGuarda();
  if(btn){ btn.classList.remove('playing'); btn.innerHTML = playIconSVG(); }
  if(statusEl) statusEl.textContent = 'Toque para ouvir';
}
window.addEventListener('beforeunload', ()=>{ try{ speechSynthesis.cancel(); }catch(e){} });

/* ================================================================
   NAVEGAÇÃO — inclui Autores & Obras, Panorama, Obra e Escrever
   ================================================================ */
function navigateTo(view){
  const anterior = state.view;
  state.view = view;
  document.querySelectorAll('.view').forEach(el=>{
    el.classList.toggle('hidden', el.dataset.view !== view);
  });
  document.querySelectorAll('[data-nav]').forEach(el=>{
    el.classList.toggle('active', el.dataset.nav === view);
  });
  window.scrollTo({ top:0, behavior: prefersReducedMotion() ? 'auto':'smooth' });
  closeMobileMenu();
  closeProfilePanel();
  if(typeof closeTraditionPanel === 'function') closeTraditionPanel();
  Musica.parar();

  if(view === 'panorama' && ['autores','explorar','descubra','historias','home','comunidade','perfil'].includes(anterior)){
    panVoltarPara = anterior;
  }

  if(view==='explorar')   renderExplore();
  if(view==='descubra')   renderDiscover();
  if(view==='historias')  renderBiographies();
  if(view==='comunidade') renderCommunityView();
  if(view==='perfil')     renderPerfil();
  if(view==='autores')    renderAutoresObras();
  if(view==='panorama')   renderPanorama();
  if(view==='obra')       renderObra();
  if(view==='escrever')   renderEscrever();

  requestAnimationFrame(()=>{ observeReveals(); wireFilterArrows(); updateFilterArrows(); });
}

/* ================================================================
   LIGAÇÕES E CARGA DA FASE 5
   ================================================================ */
function initFase5(){
  f5InjectViews();

  /* Esc fecha os novos painéis, na ordem certa */
  document.addEventListener('keydown', (e)=>{
    if(e.key !== 'Escape') return;
    const med = document.getElementById('medOverlay');
    if(med && med.classList.contains('show')) return fecharEditor();
    if(sheetAberta) return fecharSheet();
  });

  /* migração: relatos antigos continuam válidos */
  state.myPhrases.forEach(m=>{ if(m.arq === undefined) m.arq = false; if(m.del === undefined) m.del = false; });
  state.communityPosts.forEach(p=>{
    if(p.arq === undefined) p.arq = false;
    if(p.del === undefined) p.del = false;
    if(!p.comments) p.comments = [];
    if(!p.likes) p.likes = [];
    if(!p.reports) p.reports = [];
  });

  renderAutoresObras();
  renderEscrever();
}

window.__fase5Boot = function(){
  try{ initFase5(); }catch(e){ console.error('Fase 5:', e); }
};

