const F28 = { adicionadas:0, ignoradas:0 };
(function adicionarF28(){
  const cats = CATEGORIES.map(c=>c.id);
  const existentes = new Set(QUOTES.map(q=>_normDup(q.text)));
  NOVAS_F28.forEach(([autor, texto, orig, fonte, cat])=>{
    if(!texto || existentes.has(_normDup(texto))){ F28.ignoradas++; return; }
    const incerta = /^Atribuído|sem localiza|sem registro|não constam|não é de|de autoria anônima|é de Muste|é de Carl Bard|é de Megginson|não de Turing|Provérbio de origem/i.test(fonte);
    const q = { author:autor, text:texto, src:fonte, st: incerta ? 'A-' : 'A',
      cat: cats.includes(cat) ? cat : 'reflexao' };
    if(orig) q.orig = orig;
    q.qid = 'f28' + (F28.adicionadas).toString(36) + Math.abs(_normDup(texto).length*15485863).toString(36);
    QUOTES.push(q); existentes.add(_normDup(texto)); F28.adicionadas++;
  });
  reindexarQuotes();
  if(typeof reconstruirIndices === 'function') reconstruirIndices();
  RECALCULAR_FILA();
})();
window.F28 = F28;

(function bootF28(){
  const anterior = window.__fase5Boot;
  window.__fase5Boot = function(){
    try{ if(anterior) anterior(); }catch(e){ console.error('Fase anterior:', e); }
    try{ if(typeof reconstruirIndices==='function') reconstruirIndices(); reindexarQuotes(); RECALCULAR_FILA();
      console.info('MeMotiva · Fase 28: ' + F28.adicionadas + ' frases adicionadas com fonte identificada.');
    }catch(e){ console.error('Fase 28:', e); }
  };
})();



