const F31 = { adicionadas:0, ignoradas:0 };
(function adicionarF31(){
  const cats = CATEGORIES.map(c=>c.id);
  const existentes = new Set(QUOTES.map(q=>_normDup(q.text)));
  NOVAS_F31.forEach(([autor, texto, orig, fonte, cat])=>{
    if(!texto || existentes.has(_normDup(texto))){ F31.ignoradas++; return; }
    const incerta = /^Atribuído|sem localiza|sem registro|sem obra|Ver o veredito|difundida|Formulação/i.test(fonte);
    const q = { author:autor, text:texto, src:fonte, st: incerta ? 'A-' : 'A',
      cat: cats.includes(cat) ? cat : 'reflexao' };
    if(orig) q.orig = orig;
    q.qid = 'f31' + (F31.adicionadas).toString(36) + Math.abs(_normDup(texto).length*32452843).toString(36);
    QUOTES.push(q); existentes.add(_normDup(texto)); F31.adicionadas++;
  });
  reindexarQuotes();
  if(typeof reconstruirIndices === 'function') reconstruirIndices();
  RECALCULAR_FILA();
})();
window.F31 = F31;

(function bootF31(){
  const anterior = window.__fase5Boot;
  window.__fase5Boot = function(){
    try{ if(anterior) anterior(); }catch(e){ console.error('Fase anterior:', e); }
    try{ if(typeof reconstruirIndices==='function') reconstruirIndices(); reindexarQuotes(); RECALCULAR_FILA();
      console.info('MeMotiva · ' + QUOTES.length + ' frases · ' + Object.keys(OBRA_PAGINA).length + ' páginas de obra.');
    }catch(e){ console.error('Fase 31:', e); }
  };
})();



