  function aplicar(){
    var add=0, orf=[];
    for(var k in P){
      var i=k.indexOf('||'), a=k.slice(0,i), t=k.slice(i+2);
      var l=(typeof OBRAS!=='undefined'&&OBRAS[a])||null;
      if(!l||!l.some(function(o){return o.t===t;})){ orf.push(k); continue; }
      if(!OBRA_PAGINA[k]){ OBRA_PAGINA[k]=P[k]; add++; }
    }
    if(orf.length) console.warn('Fase 53b · ignoradas:', orf.join(' | '));
    console.log('MeMotiva · Fase 53b: +'+add+' páginas de obra.');
  }
  var prev=window.__fase5Boot;
  window.__fase5Boot=function(){ if(typeof prev==='function') prev(); aplicar(); };
