 function aplicar(){
  var n=0, naoAchou=[];
  CORRIGE.forEach(function(c){
   var alvo = QUOTES.filter(function(q){ return q.author===c[0] && q.text.indexOf(c[1])===0; });
   if(alvo.length!==1){ naoAchou.push('corrigir: '+c[0]+' ('+alvo.length+')'); return; }
   alvo[0].text = c[2];
   alvo[0].orig = c[3];
   n++;
  });
  var r=0;
  SAIR.forEach(function(p){
   var alvo = QUOTES.filter(function(q){ return q.author===p[0] && q.text.indexOf(p[1])===0; });
   if(alvo.length!==1){ naoAchou.push('retirar: '+p[0]+' ('+alvo.length+')'); return; }
   var res = (typeof removerFrase==='function')
     ? removerFrase(alvo[0].qid, 'condensação de passagem já presente em versão completa')
     : {ok:false};
   if(res && res.ok) r++;
  });
  if(typeof reindexarQuotes==='function') reindexarQuotes();
  if(typeof reconstruirIndices==='function') reconstruirIndices();
  if(naoAchou.length) console.warn('Fase 83 · não localizadas:', naoAchou.join(' | '));
  console.log('MeMotiva · Fase 83: '+n+' traduções acertadas com o original citado, '+r+' retirada por redundância.');
 }
