  var cats = (typeof CATEGORIES!=='undefined') ? CATEGORIES.map(function(c){return c.id;}) : [];
  var norm = function(s){ return String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]/g,''); };
