 function corrigirFonte(autor, prefixo, novaFonte, orig){
  var q = QUOTES.filter(function(x){ return x.author===autor && x.text.indexOf(prefixo)===0; })[0];
  if(!q) return {ok:false, motivo:'não encontrada: '+autor+' — '+prefixo.slice(0,40)};
  q.src = novaFonte;
  if(orig) q.orig = orig;
  delete q.fonteGenerica;
  q.procTexto = null;
  return {ok:true};
 }
